INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$e51350e8-8bac-54d9-a78a-31c1a8012303$ml$::uuid, $ml$neuroscience$ml$, 1, 1, $ml${"id": "neuroscience-d1-c1", "title": "A stroke treated through the cerebellum", "lessonTitle": "The brain in four regions", "slot": 1, "type": "apply", "brief": {"headline": "In 2023, a Cleveland Clinic trial put stimulating electrodes in the cerebellum of 12 stroke survivors with weak arms. Nine of the 12 improved, alongside physical therapy.", "kicker": "Apply the map: why treat a stroke through the cerebellum?", "fullText": "The 12 volunteers had chronic, moderate to severe weakness in one arm after a stroke 12 to 36 months earlier. Surgeons implanted deep brain stimulation electrodes in the dentate nucleus, part of the cerebellum, and stimulation ran for four to eight months alongside physical therapy.\n\nNine of the 12 improved, and the gains held after the device was switched off. People who still had some hand function gained the most, with scores almost tripling; those with little hand function gained little. The NIH BRAIN Initiative funded the phase 1 trial, published in Nature Medicine in August 2023, and said larger, randomized trials are needed.\n\nWhy the cerebellum? It coordinates movement, and decades of animal work pointed to a circuit linking the dentate nucleus to the motor cortex. Know the map, and you know where to aim.", "sources": [{"url": "https://www.nih.gov/news-events/news-releases/cerebellar-post-stroke-deep-brain-stimulation-appears-safe-feasible-small-trial", "label": "NIH, Cerebellar post-stroke deep brain stimulation appears safe and feasible, Aug 2023"}, {"url": "https://newsroom.clevelandclinic.org/2023/08/14/cleveland-clinic-study-shows-deep-brain-stimulation-encouraging-for-stroke-patients/", "label": "Cleveland Clinic, Deep brain stimulation encouraging for stroke patients, Aug 2023"}, {"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}]}, "evidence": {"kind": "multipleChoice", "prompt": "The trial aimed at the cerebellum to help weak arms. Which of its jobs made it the target?", "options": ["Coordinating movement", "Running heart rate and breathing", "Storing and retrieving memories"], "correctIndex": 0, "explanation": "The cerebellum coordinates movement, and its dentate nucleus links to the motor cortex. Breathing belongs to the brainstem, memory to the hippocampus."}, "numbers": {"kind": "numberSense", "prompt": "Nine of the 12 participants improved. What share is that?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "Nine of 12 is 75%, a promising start from a small trial that still needs larger, randomized follow-up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a company that wants to treat stroke through the cerebellum.", "prompt": "Which question shows you get the science?", "options": ["How many patents does the company hold so far?", "Why not aim the electrodes at the brainstem?", "How is the target wired to the motor cortex?"], "correctIndex": 2, "consequences": ["Patents matter later; first show you know why the target fits.", "The brainstem runs heart rate and breathing, not arm coordination.", "The dentate nucleus to motor cortex circuit is why the target makes sense."], "explanation": "The trial aimed at the dentate nucleus because of its circuit to the motor cortex. Asking about the circuit shows you think from the map."}, "proReasoning": "Strong candidates ask what a device targets and why that region fits the lost function. Here, the cerebellum coordinates movement and connects to the motor cortex.", "commonMistake": "Assuming a stroke must be treated exactly where it struck.", "mentalModel": "Aim at the circuit, not just the damage."}, "invest": {"call": {"kind": "theCall", "situation": "The trial reports 9 of 12 patients improved. A friend wants to buy into the company commercializing it.", "prompt": "What should temper the excitement?", "options": ["A 12-person trial still needs larger ones", "Gains vanished once the device was off", "The cerebellum holds few neurons"], "correctIndex": 0, "consequences": ["The NIH called the results preliminary and asked for larger, randomized trials.", "The gains persisted after stimulation was turned off.", "It holds about 80% of the brain's neurons."], "explanation": "Nine of 12 is promising, but small early trials often look better than larger ones. The NIH itself called for randomized trials."}, "proReasoning": "Investors read a phase 1 result as a reason to watch, not as proof. Trial size, controls and who benefits most all matter.", "commonMistake": "Treating 9 of 12 as a proven success rate.", "mentalModel": "Small trial, early signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building rehab software to pair with cerebellar stimulation. The trial showed who gained most.", "prompt": "Who should your first users be?", "options": ["Everyone who has ever had a stroke", "Survivors who kept some hand function", "Survivors with no hand movement at all"], "correctIndex": 1, "consequences": ["Too broad, and many would not respond.", "They gained the most, with scores almost tripling.", "Those with little hand function showed minimal benefit."], "explanation": "In the trial, people with some remaining hand function made the biggest gains. Start where the therapy works best."}, "proReasoning": "Founders start with the group the evidence favors. A narrow first user, chosen from data, beats a broad one chosen from hope.", "commonMistake": "Picking the users with the most need instead of the most benefit.", "mentalModel": "Start where the evidence is strongest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is puzzled: why put electrodes in the cerebellum to help a stroke survivor move an arm?", "prompt": "What's the best answer?", "options": ["Every stroke starts in the cerebellum", "It controls breathing during therapy", "It coordinates movement"], "correctIndex": 2, "consequences": ["Strokes strike many places; this trial chose its target by function.", "The brainstem, not the cerebellum, runs breathing.", "And a circuit links its dentate nucleus to the motor cortex."], "explanation": "The cerebellum coordinates movement, and its dentate nucleus connects to the motor cortex. Stimulating it aims to help the movement system relearn."}, "proReasoning": "Explain a treatment by the job of the region it targets. The cerebellum's job is coordination, which is what a weak arm needs.", "commonMistake": "Thinking treatment must go exactly where the damage is.", "mentalModel": "Regions work in circuits."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9cac9c8a-6d28-5475-be64-38c046644a9a$ml$::uuid, $ml$neuroscience$ml$, 1, 2, $ml${"id": "neuroscience-d1-c2", "title": "Biggest region, fewer neurons", "lessonTitle": "The brain in four regions", "slot": 2, "type": "connect", "brief": {"headline": "The cerebrum is the brain's largest part, yet its outer cortex holds about 16 billion neurons. The smaller cerebellum holds about 69 billion, or 80%.", "kicker": "Connect two day 1 ideas: the map of jobs and the count of neurons.", "fullText": "Day 1 gave you two ways to look at the brain. The first is the map: the cerebrum handles thinking and planning, the limbic system emotion and memory, the brainstem vital functions, and the cerebellum coordination. The second is the count: of about 86 billion neurons, about 69 billion sit in the cerebellum and about 16 billion in the cerebral cortex.\n\nPut them together and size stops being a guide. The region that looks biggest is not the one with the most neurons, and neither size nor count tells you a region's job. You need the map for that.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The cerebellum holds about 80% of the brain's neurons.", "The largest region holds the most neurons.", "The brainstem links the brain to the spinal cord."], "fakeIndex": 1, "explanation": "The cerebrum is the largest part, but the smaller cerebellum holds about 80% of the neurons."}, "numbers": {"kind": "numberSense", "prompt": "What share of the brain's neurons sit in the cerebral cortex?", "min": 0, "max": 100, "value": 19, "unit": "%", "explanation": "About 16 of 86 billion, or 19%. The largest part of the brain holds under a fifth of its neurons."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a neurotech interview, you're asked which brain region holds the most neurons.", "prompt": "Which answer lands best?", "options": ["The cerebellum, about 80% of them", "The cerebral cortex, since it is largest", "The brainstem, since it runs vital signs"], "correctIndex": 0, "consequences": ["Azevedo and colleagues counted about 69 of 86 billion there.", "The cortex is large but holds about 19%.", "The brainstem runs vital functions; it is not where most neurons sit."], "explanation": "The cerebellum holds about 80% of neurons. Knowing the counterintuitive fact, with a number, stands out."}, "proReasoning": "A precise number with its source beats a guess from size. Interviewers notice when you know the surprising fact.", "commonMistake": "Assuming the biggest region holds the most cells.", "mentalModel": "Count, don't eyeball."}, "invest": {"call": {"kind": "theCall", "situation": "A startup says its device reaches most of the brain's neurons because it covers the cortex.", "prompt": "How do you read the claim?", "options": ["Unclear, since nobody has counted neurons", "Wrong, since the cortex holds about 19%", "Right, since the cortex is the largest part"], "correctIndex": 1, "consequences": ["Azevedo and colleagues counted them in 2009.", "The cerebellum holds about 80%, so the claim fails a basic check.", "Largest in size, but not in neuron count."], "explanation": "The cortex holds about 16 of 86 billion neurons. A pitch that gets this wrong has a rigor problem."}, "proReasoning": "Investors check a pitch's basic science first. A wrong anatomy claim says something about the team's rigor.", "commonMistake": "Letting a confident claim pass because it sounds plausible.", "mentalModel": "Check the claim against the count."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're picking a first target for a brain device. A cofounder wants the region with the most neurons.", "prompt": "What should decide the target?", "options": ["The region with the most neurons", "The largest region by size", "The job you want to restore"], "correctIndex": 2, "consequences": ["Most neurons sit in the cerebellum, which only helps if you need coordination.", "Size says little about a region's job.", "Each region runs different jobs, so the lost function picks the target."], "explanation": "Each region runs different jobs. Start from the function patients lose, then find the region that runs it."}, "proReasoning": "Founders start from the function patients lose, then find the region that runs it. Neuron counts and size are trivia without that.", "commonMistake": "Choosing a target for its size or cell count.", "mentalModel": "Function first, then the region."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the cortex must hold most of the brain's neurons, since it's the biggest part.", "prompt": "What's a fair reply?", "options": ["Most neurons are in the small cerebellum", "Yes, the cortex holds nearly all neurons", "The brainstem holds most of the neurons"], "correctIndex": 0, "consequences": ["About 69 of 86 billion neurons sit there, so size misleads.", "It holds about 16 billion, or 19%.", "The brainstem runs vital signs; the cerebellum holds most neurons."], "explanation": "The cerebellum, below and behind the rest of the brain, holds about 80% of its neurons."}, "proReasoning": "Use one surprising number to reframe a belief. The cerebellum's 80% shows that size and cell count are different questions.", "commonMistake": "Equating the biggest part with the most neurons.", "mentalModel": "Size misleads."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$20ec0c3a-0369-5017-9068-a29052c338e9$ml$::uuid, $ml$neuroscience$ml$, 1, 3, $ml${"id": "neuroscience-d1-c3", "title": "Pick the region, pick the patients", "lessonTitle": "The brain in four regions", "slot": 3, "type": "decide", "brief": {"headline": "You run a small fund choosing among three brain device startups. One targets memory, one movement and one breathing control. Each region means different patients.", "kicker": "Decide which region each pitch really targets.", "fullText": "You run a small fund that backs early brain device companies. Three pitches arrive. One wants to help people who lose memories, one people whose movements are clumsy and uncoordinated, and one people whose breathing and heart rate are unstable.\n\nDay 1's map tells you where each must work. Deep structures in the limbic system govern emotion and memory, and the hippocampus sends memories to storage and retrieves them. The cerebellum coordinates movement. The brainstem, which links the brain to the spinal cord, runs heart rate, breathing and blood pressure. The region tells you the job, and the job tells you the patients.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which region would each product need to act on?", "buckets": ["Limbic system", "Cerebellum", "Brainstem"], "items": [{"text": "A device to help recall new memories", "bucket": 0}, {"text": "A therapy for emotional regulation", "bucket": 0}, {"text": "A device to steady a clumsy walk", "bucket": 1}, {"text": "A tool that merges input from eyes and ears", "bucket": 1}, {"text": "A device to stabilize breathing", "bucket": 2}, {"text": "A device to steady heart rate", "bucket": 2}], "explanation": "Memory and emotion sit in the limbic system, coordination in the cerebellum, and vital functions in the brainstem."}, "numbers": {"kind": "numberSense", "prompt": "The cerebellum holds about 69 billion neurons and the cortex about 16 billion. About how many times as many is that?", "min": 0, "max": 10, "value": 4.3, "unit": "times", "explanation": "69 divided by 16 is a little over 4. The smaller region holds more than four times the neurons."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at the memory startup. The founder asks where in the brain its device must act.", "prompt": "What do you answer?", "options": ["The brainstem, near the spinal cord", "The hippocampus, in the limbic system", "The cerebellum, which holds most neurons"], "correctIndex": 1, "consequences": ["The brainstem runs vital functions like breathing.", "The hippocampus sends memories to storage and retrieves them later.", "The cerebellum coordinates movement, not memory."], "explanation": "Memory runs through the hippocampus, a deep structure in the limbic system."}, "proReasoning": "Name the structure and its job in one breath. It shows you can connect a product to the anatomy.", "commonMistake": "Picking the region with the most neurons instead of the right job.", "mentalModel": "Job first, then structure."}, "invest": {"call": {"kind": "theCall", "situation": "You can back only one of the three. You want the clearest link from region to patients to market.", "prompt": "What should you ask each founder first?", "options": ["How many neurons the region holds", "How big the region looks on a scan", "Which lost function, and in whom?"], "correctIndex": 2, "consequences": ["Neuron count does not tell you who the patients are.", "Size on a scan says little about a market.", "The region's job defines the patients, and the patients define the market."], "explanation": "Movement, memory and vital functions each mean different people. The lost function tells you the market."}, "proReasoning": "Investors trace a brain product from region to job to patients. Movement, memory and vital functions each mean very different people.", "commonMistake": "Judging a pitch by the anatomy's size rather than the patients.", "mentalModel": "Region, job, patients, market."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded the breathing control startup. A partner suggests also claiming memory benefits to widen the market.", "prompt": "What's the sound call?", "options": ["Stay with the brainstem job you can show", "Add memory claims to look bigger", "Switch to the cerebellum for more neurons"], "correctIndex": 0, "consequences": ["A device acting on vital functions has no basis for memory claims.", "Memory runs through the limbic system, not the brainstem.", "More neurons does not make it the right target."], "explanation": "Your device works on brainstem jobs. Claims should stay inside what that region runs."}, "proReasoning": "Founders keep claims inside the function their target region runs. Stretching to other jobs invites doubt.", "commonMistake": "Widening claims beyond what the region does.", "mentalModel": "Claim what your region runs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why doctors check breathing and heart rate after an injury to the brainstem.", "prompt": "What's the reason?", "options": ["The cortex controls every breath", "The brainstem runs those vital functions", "The cerebellum stores the heartbeat rhythm"], "correctIndex": 1, "consequences": ["The cortex runs thinking and planning; breathing sits in the brainstem.", "It links the brain to the spinal cord and runs heart rate and breathing.", "The cerebellum coordinates movement."], "explanation": "Heart rate, breathing and blood pressure run through the brainstem, so damage there threatens them."}, "proReasoning": "Each region runs different jobs, so damage shows up as lost functions. That is why doctors test the jobs a region runs.", "commonMistake": "Thinking the whole brain does everything together.", "mentalModel": "Damage shows the region's job."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$115321e0-d186-56e1-9d7b-6cce0c119de8$ml$::uuid, $ml$neuroscience$ml$, 2, 1, $ml${"id": "neuroscience-d2-c1", "title": "Synchron's $200 million", "lessonTitle": "Three streams of brain money", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Synchron raised $200 million to move its brain implant toward market. It had implanted 10 people with paralysis and was still preparing a commercial launch.", "kicker": "Apply the three streams: which one pays for an implant before sales?", "fullText": "Synchron's Stentrode reaches the motor cortex through blood vessels, placed with a catheter instead of open brain surgery. By November 2025 it had been implanted in 10 people with paralysis, in trials in the US and Australia.\n\nOn November 6, 2025, the company closed a $200 million Series D led by Double Point Ventures, bringing its total raised to $345 million. The money is for pivotal trials, preparing a commercial launch and building a next-generation interface with more channels.\n\nOf day 2's three streams, investors, drug sales and public grants, investors are the one carrying Synchron toward market.", "sources": [{"url": "https://www.mddionline.com/neurological/synchron-snags-200m-to-move-its-bci-tech-closer-to-market", "label": "MD+DI, Synchron snags $200M to move its BCI tech closer to market, Nov 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Synchron's path to market in order.", "steps": ["The implant reaches the motor cortex through a vessel", "Early trials implant 10 people with paralysis", "Investors put in a $200 million round", "Pivotal trials test the implant at scale", "A commercial launch follows, if approved"], "explanation": "Investor money pays for the trials that come before any sales. Revenue is the last link in the chain."}, "numbers": {"kind": "numberSense", "prompt": "Synchron had raised $345 million and implanted 10 people. About how much is that per patient, in millions?", "min": 0, "max": 100, "value": 34.5, "unit": "M", "explanation": "About $34.5 million per patient so far. Investors are paying for the future, not for today's ten implants."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Synchron offers you a job in late 2025, right after its $200 million round.", "prompt": "What does its funding tell you about the role?", "options": ["Pay depends on investors until sales begin", "Product sales already cover salaries", "Grants guarantee the job for a decade"], "correctIndex": 0, "consequences": ["It is still preparing a launch, so investor money funds the work.", "It was still preparing its commercial launch.", "Its new money came from investors, not a grant."], "explanation": "A pre-launch device company lives on investor rounds. That money is plentiful after a raise but tied to hitting milestones."}, "proReasoning": "Before joining a neurotech startup, ask how long the last round lasts and which milestone earns the next one.", "commonMistake": "Assuming a big round means the company pays its own way.", "mentalModel": "Know who pays your salary."}, "invest": {"call": {"kind": "theCall", "situation": "You're offered shares in Synchron's next round. It has 10 patients implanted and no sales yet.", "prompt": "What are you really paying for?", "options": ["A guaranteed FDA approval", "The chance pivotal trials succeed", "Revenue from its current implants"], "correctIndex": 1, "consequences": ["No trial result or approval is guaranteed.", "With 10 patients, value rests on what trials still have to show.", "There is no product revenue before approval and launch."], "explanation": "Before sales, a device company is a bet on its trials. The price reflects odds, not cash flow."}, "proReasoning": "Investors in pre-revenue neurotech price a probability, not a cash flow. Ask what each milestone proves and what is still a bet.", "commonMistake": "Valuing a pre-launch company as if sales were coming in.", "mentalModel": "Pre-revenue means pricing the odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your BCI startup has 2 patients implanted. You hear Synchron raised $200 million with 10.", "prompt": "Which funding stream fits your stage?", "options": ["Product sales, starting next quarter", "Wait for NIH to fund a pivotal trial", "Investors, matched to clear milestones"], "correctIndex": 2, "consequences": ["An implant still in trials has no product to sell.", "BRAIN Initiative funding fell from $680 million to $321 million.", "Like Synchron, you raise on milestones until you can sell."], "explanation": "Device startups raise from investors against milestones. Sales come last, and public grants are shrinking."}, "proReasoning": "Founders match the money to the stage. Implant startups raise from investors against milestones, since grants are shrinking and sales come last.", "commonMistake": "Planning on revenue before the device is approved.", "mentalModel": "Match the money to the stage.", "sources": [{"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}]}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company with nothing on sale can raise $200 million.", "prompt": "What's the best explanation?", "options": ["Investors bet on future sales", "The government paid for the round", "Patients prepaid for their implants"], "correctIndex": 0, "consequences": ["Investors buy a share of what the implant might earn later.", "The round was led by Double Point Ventures, an investor.", "The implants so far went to people in trials."], "explanation": "Investors fund years of trials in exchange for a share of a possible large market later."}, "proReasoning": "Explain startup funding as a bet on the future. Investors pay for years of trials hoping for a large market later.", "commonMistake": "Assuming money only follows existing sales.", "mentalModel": "Investors buy the future."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0c8177e8-e820-5da1-8bad-2a48f0c6a8fd$ml$::uuid, $ml$neuroscience$ml$, 2, 2, $ml${"id": "neuroscience-d2-c2", "title": "Memory sells, movement raises", "lessonTitle": "Three streams of brain money", "slot": 2, "type": "connect", "brief": {"headline": "Leqembi, an Alzheimer's drug, launched at $26,500 a year. Neuralink, helping people with paralysis, raised $650 million with five people implanted. Different jobs, different money.", "kicker": "Connect day 1 and day 2: the job a product targets shapes its money.", "fullText": "On day 1 you learned that each region runs different jobs: memory through the limbic system and hippocampus, coordination through the cerebellum, vital functions through the brainstem. On day 2 you met three streams of money.\n\nLeqembi treats Alzheimer's disease, where memory fails, and earns through drug sales at $26,500 a year per patient. Neuralink's implant lets people with severe paralysis control devices with their minds; with five people implanted, it ran on investor money, $650 million in June 2025. Public grants fund much of the research behind both, and NIH BRAIN Initiative funding fell from $680 million in fiscal 2023 to $321 million in fiscal 2025.", "sources": [{"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}, {"url": "https://biopharma-reporter.com/Article/2023/01/10/Next-steps-for-lecanemab-Eisai-reveals-pricing-US-and-global-rollout-plans", "label": "BioPharma Reporter, Eisai reveals Leqembi pricing"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}]}, "evidence": {"kind": "faceOff", "prompt": "Which one earns from sales to patients today?", "left": {"name": "Leqembi", "note": "Alzheimer's drug, $26,500 a year"}, "right": {"name": "Neuralink", "note": "Brain implant, five people by June 2025"}, "correctIndex": 0, "explanation": "Leqembi is a launched drug that earns from patients. Neuralink was still in trials, funded by investors."}, "numbers": {"kind": "numberSense", "prompt": "NIH BRAIN Initiative funding fell from $680 million to $321 million. By about what percent?", "min": 0, "max": 80, "value": 53, "unit": "%", "explanation": "A drop of $359 million, about 53%. The public stream shrank while the investor stream grew."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from Eisai's Leqembi team and from a BCI startup like Neuralink.", "prompt": "What's the key difference in who pays you?", "options": ["There is no real difference", "Drug sales versus investor rounds", "Grants versus drug sales"], "correctIndex": 1, "consequences": ["Their money comes from different streams with different risks.", "A launched drug earns from patients; a startup lives on its next raise.", "Neither offer rests mainly on grants."], "explanation": "Leqembi earns from patients. A BCI startup lives on investor rounds until it can sell."}, "proReasoning": "Know which stream pays your salary. Sales depend on patients and payers; rounds depend on investors' confidence and milestones.", "commonMistake": "Treating every brain company as the same kind of employer.", "mentalModel": "Different streams, different risks."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Leqembi's maker with a BCI startup. Both serve people with brain disease.", "prompt": "What drives each one's value most?", "options": ["NIH grants pay for both of them", "The size of the region each one targets", "Patients for one, trials for the other"], "correctIndex": 2, "consequences": ["Neither company's value rests on grants, which are shrinking anyway.", "Region size says nothing about value.", "Drug revenue scales with patients; the startup's value with trial progress."], "explanation": "A launched drug is valued on patients and price. A pre-revenue implant is valued on its trials."}, "proReasoning": "Investors map each company to its stream. For a launched drug, track patients and price; for an implant, track trials and runway.", "commonMistake": "Valuing a pre-revenue implant on the same terms as a selling drug.", "mentalModel": "Know the stream before the valuation."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup targets movement, like Neuralink. A mentor says to plan revenue like Leqembi from day one.", "prompt": "What's wrong with that plan?", "options": ["You need investors long before sales", "Implants always cost less than drugs", "The NIH sets prices for devices"], "correctIndex": 0, "consequences": ["Neuralink raised $650 million while still in trials.", "Price depends on the product and the payer, not the category.", "The NIH funds research; it does not set prices."], "explanation": "An implant earns nothing until it is approved and sold. Until then, investors are the stream."}, "proReasoning": "Founders of implant companies plan years of investor funding before any sales. Pricing matters later; runway matters now.", "commonMistake": "Planning revenue like a launched drug before the device is approved.", "mentalModel": "Runway first, price later."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Alzheimer's drugs and brain implants seem funded so differently.", "prompt": "What's the short answer?", "options": ["Insurance already pays for brain implants", "One earns from sales, the other from investors", "Both are mostly paid for by the NIH"], "correctIndex": 1, "consequences": ["Neuralink's implant was still in trials with five people.", "Leqembi sells at $26,500 a year; Neuralink raised $650 million.", "NIH BRAIN funding fell to $321 million in fiscal 2025."], "explanation": "A launched drug earns from patients. An implant in trials runs on investor money."}, "proReasoning": "Follow the money stream to explain how a field behaves. Drug sales reward patients treated; investor money rewards progress.", "commonMistake": "Assuming all medical research is funded the same way.", "mentalModel": "Each stream rewards something different."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$8faab938-7e4c-526a-8f65-dc68cab99c65$ml$::uuid, $ml$neuroscience$ml$, 2, 3, $ml${"id": "neuroscience-d2-c3", "title": "Grant, spinout or both", "lessonTitle": "Three streams of brain money", "slot": 3, "type": "decide", "brief": {"headline": "You run a university lab building a brain implant. Your NIH grant ends next year, BRAIN Initiative funding has more than halved, and a venture firm offers seed money for a spinout.", "kicker": "Decide how to fund the next stage of your lab's work.", "fullText": "You run a university lab developing a brain implant. Your NIH grant ends next year. Across the BRAIN Initiative, funding fell from $680 million in fiscal 2023 to $402 million in fiscal 2024 and $321 million in fiscal 2025.\n\nA venture firm offers seed money to spin the implant out as a company. Neuralink shows how big that stream can get: $650 million in June 2025, with five people implanted. Investors expect milestones in return, and drug-style sales only come after approval.", "sources": [{"url": "https://braininitiative.nih.gov/funding/understanding-brain-initiative-budget", "label": "NIH BRAIN Initiative, Understanding the budget"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which plan spreads your lab's funding risk best?", "options": ["Take seed money and drop all grant work", "Keep applying for grants and test the spinout", "Bet everything on one more NIH grant"], "correctIndex": 1, "explanation": "With grants shrinking, a second stream lowers risk. Keeping grant work protects the science while investors test the business."}, "numbers": {"kind": "numberSense", "prompt": "From fiscal 2024 to 2025, BRAIN Initiative funding fell from $402 million to $321 million. How big a drop, in millions?", "min": 0, "max": 200, "value": 81, "unit": "M", "explanation": "$81 million less in one year, on top of a $278 million drop the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a postdoc in the lab. The spinout offers you a job; the lab can fund you one more year.", "prompt": "What should you weigh most?", "options": ["Which job has the bigger title", "Whether grants will bounce back", "How long the seed money lasts"], "correctIndex": 2, "consequences": ["Titles matter less than how long the money lasts.", "BRAIN funding fell two years running, so a rebound is a guess.", "Investor money runs out unless milestones bring the next round."], "explanation": "A seed round buys a fixed amount of time. Your job depends on hitting the milestone before it runs out."}, "proReasoning": "Researchers moving to startups ask about runway and milestones. A seed round buys time, not certainty.", "commonMistake": "Choosing on title or salary without asking how long the money lasts.", "mentalModel": "Ask how long the money lasts."}, "invest": {"call": {"kind": "theCall", "situation": "You're the venture firm. The lab's implant has worked in early tests, and its grant ends next year.", "prompt": "What makes this a good time to invest?", "options": ["Shrinking grants leave a funding gap", "The NIH guarantees follow-on funding", "Product sales will start within a year"], "correctIndex": 0, "consequences": ["With grants falling, your seed money fills a real gap.", "The NIH guarantees nothing, and its BRAIN budget fell.", "An implant in early tests is years from any sales."], "explanation": "When public money pulls back, good science looks for new funders. That is when early investors get in."}, "proReasoning": "Investors watch where public money pulls back. Good science losing its main funder can be a chance to back it early.", "commonMistake": "Assuming public funding will carry a project to market.", "mentalModel": "Watch where grants pull back."}, "build_startup": {"call": {"kind": "theCall", "situation": "You take the seed money and found the spinout. Investors want a milestone within 18 months.", "prompt": "Which milestone best earns the next round?", "options": ["A press tour about the technology", "Safety results in more patients", "A bigger office near the university"], "correctIndex": 1, "consequences": ["Attention without data rarely earns a bigger round.", "Neuralink raised after implanting five people; evidence drives rounds.", "Space costs money and proves nothing."], "explanation": "The next round pays for proof. For an implant, that means patients and safety data."}, "proReasoning": "Founders pick milestones that reduce the main risk. For an implant, that means more patients and safety data.", "commonMistake": "Spending seed money on things that do not answer investors' questions.", "mentalModel": "Each round buys one answer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many university brain projects are turning into startups.", "prompt": "What's one big reason?", "options": ["Universities must sell their labs", "Drug sales pay for lab research", "Public grants are shrinking"], "correctIndex": 2, "consequences": ["No rule forces universities to sell labs.", "Labs mostly run on grants, not drug sales.", "BRAIN Initiative funding fell by more than half from 2023 to 2025."], "explanation": "When one stream shrinks, researchers turn to the others. A spinout is how lab science reaches investor money."}, "proReasoning": "When one money stream shrinks, work moves toward the others. Spinouts are how lab science reaches investor money.", "commonMistake": "Thinking startups appear only because founders want to get rich.", "mentalModel": "Work follows the money."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$8be384c0-a10b-52d7-8221-4fdb0a698213$ml$::uuid, $ml$neuroscience$ml$, 3, 1, $ml${"id": "neuroscience-d3-c1", "title": "Paradromics gets its yes", "lessonTitle": "The brain's two gatekeepers", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, the FDA let Paradromics start a study of its fully implanted brain-computer interface, beginning with two people. The first implant came in June 2026.", "kicker": "Apply the regulator gate: what the FDA's yes did and did not allow.", "fullText": "Paradromics' Connexus implant records brain signals through a high-density microelectrode array and sends them to a receiver in the chest, which transmits them wirelessly through the skin. The goal is to restore speech and computer control for people with severe motor impairment.\n\nOn November 20, 2025, the FDA granted an investigational device exemption, or IDE, for the Connect-One early feasibility study: initially two participants, at UC Davis, Massachusetts General Hospital and the University of Michigan. On June 17, 2026, the company announced the first implant, in a Michigan woman with motor neuron disease, who will be followed for six years.\n\nThe yes allowed a study, not sales. The device stays limited by US law to investigational use.", "sources": [{"url": "https://www.businesswire.com/news/home/20251120141086/en/Paradromics-Receives-FDA-Approval-for-the-Connect-One-Clinical-Study-with-the-Connexus%C2%AE-Brain-Computer-Interface/", "label": "Paradromics via Business Wire, FDA approval for the Connect-One study, Nov 2025"}, {"url": "https://www.businesswire.com/news/home/20260617963732/en/Paradromics-and-University-of-Michigan-Complete-First-Connexus-BCI-Implantation-for-the-FDA-Approved-Connect-One-Clinical-Study", "label": "Paradromics via Business Wire, First Connexus implant in Connect-One, Jun 2026"}, {"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Paradromics' path to its first implant in order.", "steps": ["Years of animal tests show stable recordings", "The FDA grants an IDE for a small study", "Three sites screen possible participants", "The first participant is implanted", "Six years of follow-up build the safety record"], "explanation": "The FDA's yes came before any long-term implant in a person. Follow-up then runs for years."}, "numbers": {"kind": "numberSense", "prompt": "From the IDE in November 2025 to the first implant in June 2026, about how many months passed?", "min": 0, "max": 24, "value": 7, "unit": "months", "explanation": "About seven months from the regulator's yes to the first person, with six years of follow-up still ahead."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Paradromics' clinical team in 2026. A friend congratulates you on the FDA approval.", "prompt": "How do you describe it accurately?", "options": ["No FDA role, since it is still research", "FDA approval to run a study, not to sell", "Full approval to market the implant"], "correctIndex": 1, "consequences": ["The FDA had to approve the study before any implant.", "An IDE lets the study go ahead; the device stays investigational.", "The device is limited by US law to investigational use."], "explanation": "An IDE allows a clinical study. Selling the device would need a separate, later approval."}, "proReasoning": "In device regulation, say which approval you mean. An IDE allows a study; clearance or approval allows sales.", "commonMistake": "Calling a study approval a market approval.", "mentalModel": "Name the approval precisely."}, "invest": {"call": {"kind": "theCall", "situation": "A headline says Paradromics is FDA approved. You hold a small stake.", "prompt": "What does the news really change?", "options": ["The device can now earn revenue", "The regulatory risk is fully over", "Human data can now start to build"], "correctIndex": 2, "consequences": ["It stays limited by US law to investigational use.", "A feasibility study is an early step on a long path.", "Two participants and six years of follow-up are the next proof points."], "explanation": "An IDE starts the clock on human data. It does not allow sales or end the regulatory risk."}, "proReasoning": "Investors translate regulatory headlines into the next proof point. A study approval starts the clock on human data; it does not end the risk.", "commonMistake": "Reading 'FDA approves study' as 'FDA approves product'.", "mentalModel": "A study yes is a start, not a finish."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your BCI startup has strong animal data and wants its first long-term human implant in the US.", "prompt": "What must come first?", "options": ["FDA approval of a study, like an IDE", "A first patient willing to try it", "A sales deal with a hospital"], "correctIndex": 0, "consequences": ["The FDA classes implanted BCIs as significant risk, so it must approve the study.", "A willing patient cannot replace the FDA's approval.", "You cannot sell an implant that has not been tested in people."], "explanation": "Implanted BCIs are significant risk devices. The FDA must approve the study before the first implant."}, "proReasoning": "Founders plan the regulator into the timeline. Paradromics went from IDE to first implant in about seven months, and follow-up runs for years.", "commonMistake": "Setting a first implant date before the FDA has approved the study.", "mentalModel": "The regulator sets the first date."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a brain implant study starts with only two people.", "prompt": "What's a sound answer?", "options": ["Nobody else wanted to get the implant", "Risky devices are tried on a few first", "The FDA caps every study at two people"], "correctIndex": 1, "consequences": ["Screening was underway at three sites.", "It is an early feasibility study, set to begin with two people.", "There is no fixed cap of two; this study starts with two."], "explanation": "The FDA classes implanted BCIs as significant risk devices. An early feasibility study starts small and follows people for years."}, "proReasoning": "Explain small first studies as risk control. With a significant risk device, you learn from a few people before many.", "commonMistake": "Reading a small study as a sign of weak demand.", "mentalModel": "Few people first, many later."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$6b6140a1-8a0a-5a6a-971f-ed921b36fc82$ml$::uuid, $ml$neuroscience$ml$, 3, 2, $ml${"id": "neuroscience-d3-c2", "title": "The gate before the round", "lessonTitle": "The brain's two gatekeepers", "slot": 2, "type": "connect", "brief": {"headline": "The FDA turned down Neuralink's requests for human testing several times before saying yes in May 2023. Two years later, with five people implanted, it raised $650 million.", "kicker": "Connect day 2 and day 3: the regulator's yes comes before big money.", "fullText": "On day 3 you saw that the FDA classes an implanted brain-computer interface as a significant risk device, and that it turned down Neuralink's requests for human testing several times before approving a first-in-human study in May 2023. On day 2 you saw what came after: a $650 million Series E in June 2025, at a reported valuation around $9 billion before the money, with five people implanted.\n\nThe order matters. Investors can fund a device company through animal tests, but people can only be implanted after the regulator says yes. Without that yes, there would have been no implanted patients to point to.", "sources": [{"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}, {"url": "https://stuff.co.za/2023/05/26/neuralink-fda-approval-human-trials/", "label": "Stuff, Neuralink gets FDA approval for human trials"}, {"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What had to happen before Neuralink could implant its first person in the US?", "options": ["It raised its $650 million round", "It sold its first implant", "The FDA approved a human study"], "correctIndex": 2, "explanation": "The FDA approved a first-in-human study in May 2023. The $650 million round came in June 2025, after five implants."}, "numbers": {"kind": "numberSense", "prompt": "From the FDA's yes in May 2023 to the $650 million round in June 2025, about how many months passed?", "min": 0, "max": 60, "value": 25, "unit": "months", "explanation": "About 25 months. The regulator opened the gate; the patients implanted after it gave investors something to price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a BCI startup with strong animal data. They ask for its biggest near-term risk.", "prompt": "What do you say?", "options": ["Hiring enough good engineers quickly", "Choosing a brand name for the launch", "Getting the FDA to approve a human study"], "correctIndex": 2, "consequences": ["Hiring matters, but the FDA decides when people can be implanted.", "Launch is years away; the regulator comes first.", "Neuralink was turned down several times before its yes."], "explanation": "For an implant, the FDA decides when human testing starts. That gate comes before everything else."}, "proReasoning": "Name the gate that blocks the next step. For an implant, that is the FDA approving human testing.", "commonMistake": "Focusing on growth problems before the regulatory gate is passed.", "mentalModel": "Name the next gate."}, "invest": {"call": {"kind": "theCall", "situation": "A BCI startup asks you to invest before the FDA has approved any human study.", "prompt": "How should that shape your terms?", "options": ["Price in the risk of FDA rejections", "Pay a Neuralink-like valuation now", "Ignore it, since FDA approval is routine"], "correctIndex": 0, "consequences": ["Neuralink was turned down several times, so delay is a real risk.", "Neuralink had five patients when it raised at about $9 billion.", "Implanted BCIs are significant risk devices, a high bar."], "explanation": "Before the FDA says yes, there is no human data. That risk belongs in the price."}, "proReasoning": "Investors value the gate as a risk. Before the FDA's yes, a device company has no human data to show.", "commonMistake": "Paying for human-stage progress before the human stage begins.", "mentalModel": "Price the gate before it opens."}, "build_startup": {"call": {"kind": "theCall", "situation": "You've just won FDA approval for a first-in-human study. Your board asks when to raise a big round.", "prompt": "What's the best timing?", "options": ["Only after full market approval", "After the first implants show data", "Today, on the approval headline alone"], "correctIndex": 1, "consequences": ["Waiting years for market approval could starve the company.", "Neuralink raised $650 million after five people were implanted.", "A study approval alone shows no human results yet."], "explanation": "Human results are worth more to investors than permission to collect them. Raise when you can show them."}, "proReasoning": "Founders time big rounds to proof points. The first human results are worth far more to investors than permission to collect them.", "commonMistake": "Raising on the permission instead of the results.", "mentalModel": "Raise on results, not permission."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Neuralink took years to implant its first person.", "prompt": "What's the key reason?", "options": ["It could not find any volunteers", "Brain implants are banned in the US", "The FDA had to approve human testing"], "correctIndex": 2, "consequences": ["Volunteers were not the bottleneck; the approval was.", "They are allowed, but need FDA approval as significant risk devices.", "The FDA turned down its requests several times before May 2023."], "explanation": "The FDA classes implanted BCIs as significant risk devices. It approved Neuralink's first human study in May 2023, after earlier rejections."}, "proReasoning": "When a tech company moves slowly, look for a gatekeeper. In brain implants, the FDA decides when human testing starts.", "commonMistake": "Assuming delays come from the technology alone.", "mentalModel": "Look for the gatekeeper."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$c7c9d95a-ae2c-5c69-819d-06ef91780d98$ml$::uuid, $ml$neuroscience$ml$, 3, 3, $ml${"id": "neuroscience-d3-c3", "title": "An antibody at the border", "lessonTitle": "The brain's two gatekeepers", "slot": 3, "type": "decide", "brief": {"headline": "You run a small biotech. Your antibody clears a brain disease protein in a dish, but essentially no large-molecule drug crosses the blood-brain barrier on its own.", "kicker": "Decide what to fix before your antibody goes into people.", "fullText": "You run a young biotech whose lead drug is an antibody, a large molecule. In lab tests it clears a protein linked to a brain disease, and your board wants to move fast.\n\nDay 3's first gatekeeper stands in the way. Pardridge wrote in 2005 that essentially 100% of large-molecule drugs and more than 98% of small-molecule drugs do not cross the blood-brain barrier. A dish has no barrier. A drug that works there can still fail in people if too little of it reaches brain tissue.", "sources": [{"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each result show the antibody gets into the brain?", "buckets": ["Shows it gets in", "Doesn't show it"], "items": [{"text": "Drug found in animal brain tissue after a dose", "bucket": 0}, {"text": "Brain levels high enough to hit the target", "bucket": 0}, {"text": "It clears the protein in a dish", "bucket": 1}, {"text": "It binds its target tightly", "bucket": 1}, {"text": "High drug levels in the blood", "bucket": 1}], "explanation": "Only measurements in the brain answer the barrier question. Dish results and blood levels can look great while the brain sees almost nothing."}, "numbers": {"kind": "numberSense", "prompt": "More than 98% of small-molecule drugs do not cross. Out of 1,000, fewer than how many get through?", "min": 0, "max": 100, "value": 20, "unit": "drugs", "explanation": "Under 2% of 1,000 is under 20. For large molecules like antibodies, essentially none."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at this biotech. The head of R&D asks what worries you about the lead drug.", "prompt": "What's your best answer?", "options": ["Whether enough antibody reaches the brain", "Whether the dish results are even real", "Whether the antibody is simply too small"], "correctIndex": 0, "consequences": ["Essentially no large-molecule drug crosses the barrier unaided.", "Possible, but the bigger known risk is the barrier.", "Antibodies are large molecules, which is the problem."], "explanation": "Antibodies are large molecules, and essentially none cross the barrier alone. Entry is the first question."}, "proReasoning": "For any brain drug, ask how it crosses the blood-brain barrier. It is the first gate, and most drugs never pass it.", "commonMistake": "Judging a brain drug by its lab potency alone.", "mentalModel": "Ask how it gets in."}, "invest": {"call": {"kind": "theCall", "situation": "The biotech asks you to fund human trials of its antibody.", "prompt": "What evidence do you want first?", "options": ["A larger team of chemists", "Proof the drug reaches brain tissue", "More dish results at higher doses"], "correctIndex": 1, "consequences": ["Team size does not get the drug across.", "Without it, the trial may test a drug the brain never sees.", "More dish results do not answer the barrier question."], "explanation": "Proof of brain entry is cheap to get early and expensive to discover missing in a trial."}, "proReasoning": "Investors in brain drugs ask for evidence the drug gets in before paying for big trials. It is the cheapest risk to test early.", "commonMistake": "Funding a trial before knowing the drug reaches its target.", "mentalModel": "Check entry before efficacy."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your antibody can't get in on its own. Your team has three ideas.", "prompt": "Which plan tackles the real problem?", "options": ["Raise the dose and hope", "Test it in a bigger dish study", "Find a way to carry it across"], "correctIndex": 2, "consequences": ["More drug in the blood still meets the same barrier.", "A dish has no barrier, so it cannot answer the question.", "Delivery is the bottleneck, so solve delivery."], "explanation": "The barrier, not the antibody, is what blocks you. Solve delivery first."}, "proReasoning": "Founders spend first on the gate that blocks them. For a large-molecule brain drug, delivery is the gate.", "commonMistake": "Improving the drug while ignoring how it reaches the brain.", "mentalModel": "Solve the gate first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why brain drugs that work in a lab so often fail in people.", "prompt": "What's one big reason?", "options": ["Most drugs cannot get into the brain", "Lab cells behave nothing like real cells", "Brain diseases have no targets to hit"], "correctIndex": 0, "consequences": ["Over 98% of small molecules and nearly all large ones are blocked.", "The cells can be fine; the dish just has no barrier.", "This antibody had a target; reaching it was the problem."], "explanation": "The blood-brain barrier blocks most drugs. A dish has no such barrier, so lab success can mislead."}, "proReasoning": "Explain the blood-brain barrier as a border guard. It protects the brain, and it also blocks most medicines.", "commonMistake": "Assuming a drug that works in a dish works in a brain.", "mentalModel": "The barrier blocks most drugs."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$cc149168-3e1c-5898-a43f-ae92e58148d4$ml$::uuid, $ml$neuroscience$ml$, 4, 1, $ml${"id": "neuroscience-d4-c1", "title": "A grain of sand, 523 million synapses", "lessonTitle": "The numbers inside your head", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, the MICrONS team mapped one cubic millimeter of mouse brain, about a grain of sand. It held more than 200,000 cells, 523 million synapses and 4 kilometers of axons.", "kicker": "Apply the lesson: count, don't judge the brain by its size.", "fullText": "MICrONS recorded a mouse's visual cortex while it watched movies and YouTube clips, then sliced and imaged the same tissue to trace its wiring. Published on April 9, 2025, across ten studies in the Nature journals, the map covers one cubic millimeter of tissue, no larger than a grain of sand.\n\nInside: more than 200,000 cells, 523 million synapses and about 4 kilometers of axons. The data fill 1.6 petabytes, about 22 years of continuous HD video. More than 150 scientists took part, funded by IARPA and the NIH BRAIN Initiative.\n\nA speck of tissue, and a staggering count. Size tells you almost nothing; the numbers tell you what you are dealing with.", "sources": [{"url": "https://sciencedaily.com/releases/2025/04/250409114838.htm", "label": "ScienceDaily, MICrONS maps a cubic millimeter of mouse brain, Apr 2025"}, {"url": "https://www.eurekalert.org/news-releases/1079296", "label": "EurekAlert, MICrONS wiring diagram of mouse visual cortex, Apr 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "The map covers a grain of sand of mouse cortex. How many synapses did it find inside?", "options": ["523 million", "About 5,000", "About 86 billion"], "correctIndex": 0, "explanation": "523 million synapses in one cubic millimeter. 86 billion is the neuron count of a whole human brain."}, "numbers": {"kind": "numberSense", "prompt": "About how many kilometers of axons did the map trace in that one cubic millimeter?", "min": 0, "max": 20, "value": 4, "unit": "km", "explanation": "About 4 kilometers of wiring, packed into a speck the size of a grain of sand."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're applying to a brain mapping lab. They ask why one cubic millimeter took more than 150 scientists.", "prompt": "What's your best answer?", "options": ["The tissue sample was the size of a fist", "Only a few cells needed mapping", "It held 523 million synapses to trace"], "correctIndex": 2, "consequences": ["It was no larger than a grain of sand.", "It held more than 200,000 cells.", "The count, not the size, made it a huge job."], "explanation": "The sample was tiny, but it held hundreds of millions of connections. The count set the workload."}, "proReasoning": "Explain big efforts with the number that drives them. Here, 523 million synapses in a speck of tissue.", "commonMistake": "Judging the difficulty by the sample's size.", "mentalModel": "The count sets the workload."}, "invest": {"call": {"kind": "theCall", "situation": "A startup wants to map a whole human brain at the MICrONS level of detail. It shows you the mouse results.", "prompt": "What should you check first?", "options": ["How data and costs grow with volume", "Whether the mouse watched the right movies", "How large the founders' lab is"], "correctIndex": 0, "consequences": ["One cubic millimeter already took 1.6 petabytes, so scale is the risk.", "The stimulus matters less than the mountain of data.", "Lab size says little about whether the plan can scale."], "explanation": "A grain of sand produced 1.6 petabytes. Scale the numbers before you believe the plan."}, "proReasoning": "Investors scale the numbers before backing a plan. If a grain of sand took 1.6 petabytes, ask what a whole brain would take.", "commonMistake": "Extrapolating a lab feat without doing the math.", "mentalModel": "Scale the numbers first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells tools to labs that map brain wiring. MICrONS produced 1.6 petabytes from one cubic millimeter.", "prompt": "Which product need does that point to?", "options": ["Faster tissue shipping by courier", "Storing and analyzing huge image data", "Cheaper housing for lab mice"], "correctIndex": 1, "consequences": ["Shipping a grain of sand is easy; handling its data is not.", "1.6 petabytes is about 22 years of HD video from one speck.", "Mice are not the bottleneck; data is."], "explanation": "The tissue was tiny and the data enormous. Data handling is where the pain is."}, "proReasoning": "Founders look for the number that breaks today's tools. Petabytes from a speck of tissue say data handling is a bottleneck.", "commonMistake": "Building for the visible step instead of the overwhelming one.", "mentalModel": "Build where the numbers explode."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't see why mapping a grain-sized piece of brain was news.", "prompt": "Which fact makes it click?", "options": ["It took one afternoon to scan", "It held only a few hundred cells", "It held 4 kilometers of axons"], "correctIndex": 2, "consequences": ["It took a team of more than 150 scientists.", "It held more than 200,000 cells.", "Kilometers of wiring in a grain of sand makes the point."], "explanation": "Four kilometers of axons in a speck of tissue shows why the brain is so hard to map."}, "proReasoning": "Pick one number people can picture. Kilometers of wiring in a speck of tissue does more than any adjective.", "commonMistake": "Calling the brain complex without giving a number.", "mentalModel": "One vivid number beats adjectives."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$4605948b-a065-5db4-8b22-85a68034e928$ml$::uuid, $ml$neuroscience$ml$, 4, 2, $ml${"id": "neuroscience-d4-c2", "title": "Small organ, big bill", "lessonTitle": "The numbers inside your head", "slot": 2, "type": "connect", "brief": {"headline": "The brain is about 2% of body weight but uses about 20% of resting energy. Inside it, the small cerebellum holds about 80% of the neurons.", "kicker": "Connect day 1 and day 4: two ways size misleads.", "fullText": "On day 1 you learned that the cerebellum, a wrinkled ball below and behind the rest of the brain, holds about 69 of the brain's 86 billion neurons. On day 4 you saw the energy side: the brain is about 2% of body weight, yet it uses about 20% of the body's resting energy.\n\nBoth facts break the same habit, judging by size. A small region can hold most of the cells, and a small organ can carry a large share of the body's energy bill. Check the counts and the energy, not the weight.", "sources": [{"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}, {"url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108621", "label": "BioNumbers, brain share of resting metabolism"}, {"url": "https://mayoclinic.org/brain/sls-20077047", "label": "Mayo Clinic, Brain anatomy and how the brain works"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The brain is about 2% of body weight.", "The brain uses about 2% of resting energy.", "The cerebellum holds about 69 billion neurons."], "fakeIndex": 1, "explanation": "The brain uses about 20% of resting energy, ten times its share of body weight."}, "numbers": {"kind": "numberSense", "prompt": "The brain is about 2% of body weight and uses about 20% of resting energy. How many times its weight share is that?", "min": 0, "max": 25, "value": 10, "unit": "times", "explanation": "20% against 2% is ten times. By energy, the brain punches far above its weight."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to sum up the brain in numbers.", "prompt": "Which answer is strongest?", "options": ["86 billion neurons, 20% of resting energy", "It's the body's most complex organ by far", "About 86 billion neurons, mostly in the cortex"], "correctIndex": 0, "consequences": ["Two sourced numbers show you know the brain.", "Perhaps, but it gives them nothing to check.", "The cortex holds about 19%; most sit in the cerebellum."], "explanation": "Numbers beat adjectives, as long as they are right. Most neurons sit in the cerebellum, not the cortex."}, "proReasoning": "Quote numbers that surprise: 86 billion neurons, most in the cerebellum, 20% of resting energy. They show you know the brain beyond the cliché.", "commonMistake": "Using adjectives where numbers would land.", "mentalModel": "Numbers, not adjectives."}, "invest": {"call": {"kind": "theCall", "situation": "A pitch says its brain device barely uses energy, just like the brain.", "prompt": "What's wrong with the comparison?", "options": ["Devices and brains use the same power", "The brain uses about 20% of resting energy", "The brain uses no measurable energy"], "correctIndex": 1, "consequences": ["Nothing supports that; the brain's share is about 20%.", "At 2% of body weight, the brain is an energy-hungry organ.", "It uses about a fifth of resting energy."], "explanation": "The brain is one of the hungriest organs for its size. The analogy gets the basic fact backwards."}, "proReasoning": "Investors check analogies against numbers. A pitch that gets basic brain facts wrong deserves closer scrutiny.", "commonMistake": "Accepting a vivid analogy without checking it.", "mentalModel": "Test the analogy with a number."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're writing a product brief. A teammate says the brain is too small to matter much for metabolism.", "prompt": "How do you correct the brief?", "options": ["It uses about 2% of resting energy", "Brain energy use has never been measured", "It uses about 20% of resting energy"], "correctIndex": 2, "consequences": ["2% is its share of weight, not of energy.", "BioNumbers lists it at about 20%.", "Small by weight, large on the energy bill."], "explanation": "The brain is about 2% of body weight and about 20% of resting energy. Mixing them up skews the brief."}, "proReasoning": "Founders build on the right numbers from the start. A brief built on a wrong fact leads to wrong product claims.", "commonMistake": "Confusing the brain's weight share with its energy share.", "mentalModel": "Weight and energy are different numbers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the brain can't use much energy, since it's so light.", "prompt": "What do you tell them?", "options": ["At 2% of weight, it uses about 20% of energy", "It uses about as much as a fingernail", "Brains only use energy while we think hard"], "correctIndex": 0, "consequences": ["That is about ten times its share by weight.", "It uses about 20% of resting energy.", "The 20% figure is for the body at rest."], "explanation": "The brain takes about a fifth of the energy the body uses at rest."}, "proReasoning": "One ratio does the explaining: 2% of weight, 20% of energy. It is also why the brain suffers so fast when blood stops.", "commonMistake": "Assuming energy use follows weight.", "mentalModel": "Size misleads."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$494776ee-050a-5e84-b342-e5628d5db79e$ml$::uuid, $ml$neuroscience$ml$, 4, 3, $ml${"id": "neuroscience-d4-c3", "title": "Five patients, $9 billion", "lessonTitle": "The numbers inside your head", "slot": 3, "type": "decide", "brief": {"headline": "Neuralink raised $650 million in June 2025 at a reported valuation around $9 billion before the money. It had implanted five people. You decide what those numbers prove.", "kicker": "Decide which numbers are proof and which are a bet.", "fullText": "You run a small fund that follows brain-computer interfaces. Neuralink's Series E closed in June 2025 at $650 million, and Semafor reported a pre-money valuation around $9 billion. The company said five people with severe paralysis had its implant and could control digital devices with their minds.\n\nDay 4's habit applies to companies as well as brains: check the counts. Five patients prove something real. They do not yet prove long-term safety, a large market, or that payers will cover the device. A valuation prices those unproven parts too.", "sources": [{"url": "https://techcrunch.com/2025/06/02/elon-musks-neuralink-closes-a-650m-series-e", "label": "TechCrunch, Neuralink closes a $650M Series E"}, {"url": "https://www.fiercebiotech.com/medtech/neuralink-secures-650m-series-e-funding-expand-patient-access-brain-chip-technology", "label": "FierceBiotech, Neuralink secures $650M Series E"}]}, "evidence": {"kind": "sortSignal", "prompt": "Has each claim been shown yet, or is it still a bet?", "buckets": ["Shown so far", "Still a bet"], "items": [{"text": "People have been implanted with the chip", "bucket": 0}, {"text": "Patients control devices by thought", "bucket": 0}, {"text": "Years of safety in many patients", "bucket": 1}, {"text": "Thousands of paying patients", "bucket": 1}, {"text": "Insurers covering the implant", "bucket": 1}], "explanation": "Five implants show the device can work in people. Safety at scale, demand and coverage are still ahead."}, "numbers": {"kind": "numberSense", "prompt": "A $9 billion valuation over five implanted patients is about how many billion dollars per patient?", "min": 0, "max": 5, "value": 1.8, "unit": "B", "explanation": "$9 billion divided by five is $1.8 billion each. The price is for the future, not the five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a role at a BCI company valued like Neuralink, with a handful of patients.", "prompt": "What question protects you most?", "options": ["How many followers does the CEO have?", "What milestone does the next raise need?", "How big is the new office?"], "correctIndex": 1, "consequences": ["Attention is not evidence.", "Value rests on milestones still ahead, and so does your job.", "Offices say nothing about the path to patients."], "explanation": "A company priced on the future needs the next round. Ask what it takes to get there."}, "proReasoning": "At a company priced on the future, ask which milestone the next round depends on. That tells you how secure the role is.", "commonMistake": "Reading a high valuation as job security.", "mentalModel": "Ask what the next round needs."}, "invest": {"call": {"kind": "theCall", "situation": "Your fund can join a round valuing a BCI startup at $9 billion with five patients.", "prompt": "How do you frame the decision?", "options": ["Five patients prove the market is huge", "A big round means the risk is gone", "Price what is proven and what is a bet"], "correctIndex": 2, "consequences": ["Five patients show feasibility, not market size.", "Big money raises the stakes; it does not remove risk.", "Five implants show it works; safety and market are still bets."], "explanation": "Split the story into what five patients show and what the price assumes. Then decide if the bet is worth it."}, "proReasoning": "Investors split a story into what has been shown and what is assumed. Small numbers can justify a bet, not a certainty.", "commonMistake": "Letting a large valuation stand in for proof.", "mentalModel": "Proof versus bet."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded a BCI startup with two patients. Investors keep comparing you to Neuralink's $9 billion.", "prompt": "What should you anchor your pitch on?", "options": ["What your two patients show, and what is next", "Neuralink's valuation as your benchmark", "Forecasts of millions of future users"], "correctIndex": 0, "consequences": ["Honest evidence plus a clear next step builds trust.", "Their five patients and $650 million are not your numbers.", "Forecasts without patients are a story, not evidence."], "explanation": "Pitch what your numbers prove and the next proof the money will buy."}, "proReasoning": "Founders pitch what their numbers prove and the next proof the money will buy. Borrowed valuations invite hard questions.", "commonMistake": "Anchoring on someone else's valuation.", "mentalModel": "Pitch your proof, not their price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't believe a company with five patients is worth about $9 billion.", "prompt": "What's a fair explanation?", "options": ["The FDA set the valuation", "Investors are pricing a large possible future", "Each patient pays billions for the implant"], "correctIndex": 1, "consequences": ["Investors, not regulators, set valuations.", "Five patients show it can work; the price bets on many more.", "The implants went to people in trials."], "explanation": "A valuation is a bet on what the company could become, not a measure of today's patients."}, "proReasoning": "Explain big valuations as bets on the future. The current numbers show what is possible; the price assumes much more.", "commonMistake": "Thinking a valuation reflects today's revenue.", "mentalModel": "Valuations price the future."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e4c98f2a-ab6d-55af-aecb-f6fe1826d425$ml$::uuid, $ml$neuroscience$ml$, 5, 1, $ml${"id": "neuroscience-d5-c1", "title": "Novo's lottery ticket", "lessonTitle": "Why brain drugs fail so often", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, two Phase 3 trials of semaglutide in 3,808 people with early Alzheimer's failed to slow decline. UBS had given them a 10% chance; Novo's shares fell 8% that day.", "kicker": "Apply the base rate: even a famous drug faced long odds here.", "fullText": "Semaglutide, Novo Nordisk's drug approved for diabetes and obesity, was tested in early Alzheimer's in the evoke and evoke+ trials. 3,808 people aged 55 to 85 with mild cognitive impairment or mild Alzheimer's dementia took a daily semaglutide pill or a placebo for two years.\n\nOn November 24, 2025, Novo said semaglutide did not beat placebo on the CDR-SB, a measure of cognition and function, though it improved some Alzheimer's-related biomarkers. It dropped the planned one-year extension, and its shares fell 8.32% in Copenhagen.\n\nThe odds had been stated openly. UBS put the chance of success at 10%, a senior Novo executive had called the trials a lottery ticket, and the company's chief scientific officer had acknowledged a low likelihood of success.", "sources": [{"url": "https://www.alzheimer-europe.org/news/novo-nordisk-announces-topline-results-evoke-and-evoke-trials-semaglutide-early-ad", "label": "Alzheimer Europe, Novo Nordisk topline results from evoke and evoke+, Nov 2025"}, {"url": "https://www.hl.co.uk/shares/stock-market-news/company--news/novo-nordisk-shares-fall-on-failure-of-two-big-alzheimers-studies", "label": "Hargreaves Lansdown, Novo Nordisk shares fall on failure of two Alzheimer's studies, Nov 2025"}, {"url": "https://mind.uci.edu/novo-nordisk-announces-disappointing-glp1-results/", "label": "UCI MIND, Novo Nordisk announces disappointing GLP-1 results, Nov 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the evoke trials. Tap it.", "statements": ["Semaglutide improved some Alzheimer's biomarkers.", "Semaglutide slowed decline on the CDR-SB.", "Novo dropped the planned one-year extension."], "fakeIndex": 1, "explanation": "Biomarkers moved, but decline did not slow. A better marker is not the same as a better outcome."}, "numbers": {"kind": "numberSense", "prompt": "What chance of success, in percent, had UBS given the evoke trials?", "min": 0, "max": 40, "value": 10, "unit": "%", "explanation": "About 10%, above the 5.9% average for neurology drugs from Phase 1, and still a long shot."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a role on a big drugmaker's Alzheimer's program. It's one of many bets the company runs.", "prompt": "How should the odds shape your choice?", "options": ["A failure hurts less inside a broad company", "A big company means the drug will work", "Odds only matter at small biotechs"], "correctIndex": 0, "consequences": ["Novo's shares fell 8%, but one trial was not the whole company.", "Novo's evoke trials failed despite its size.", "Neurology's 5.9% odds apply to every company."], "explanation": "Size does not change the science, but it changes what a failure does to your job."}, "proReasoning": "In neurology, judge a job by what happens if the trial fails. At a broad company, a failed program is a setback; at a one-drug biotech, it can be the end.", "commonMistake": "Assuming a famous company's program is safer science.", "mentalModel": "Ask what happens if it fails.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}]}, "invest": {"call": {"kind": "theCall", "situation": "Before the readout, Novo calls the trials a lottery ticket and UBS gives them 10%. The stock falls 8% on failure.", "prompt": "What does the drop tell you?", "options": ["The drug will be pulled from diabetes use", "Some investors had priced in more hope", "The odds had been 90% in favor"], "correctIndex": 1, "consequences": ["The failure was in Alzheimer's, not its approved uses.", "Even long shots carry value until they fail.", "UBS put the chance at 10%, not 90%."], "explanation": "A 10% chance at a huge market is worth something. When it fails, that value comes out of the price."}, "proReasoning": "Investors size how much a binary event is worth before it happens. A 10% chance still carries value, and losing it moves the price.", "commonMistake": "Thinking a widely expected failure cannot move the stock.", "mentalModel": "Long shots carry value until they fail."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's Alzheimer's drug improves biomarkers in early tests. You're planning a pitch.", "prompt": "What lesson from evoke should shape it?", "options": ["Biomarker gains guarantee clinical success", "Large trials always succeed", "Better biomarkers may not slow decline"], "correctIndex": 2, "consequences": ["Evoke improved biomarkers and still failed.", "3,808 people did not save evoke.", "Semaglutide moved biomarkers but did not beat placebo on the CDR-SB."], "explanation": "Evoke showed that markers can move while patients still decline. Plan your evidence for that gap."}, "proReasoning": "Founders show they know the gap between markers and outcomes. Investors trust a team that plans for it.", "commonMistake": "Pitching biomarker gains as proof of benefit.", "mentalModel": "Markers are not outcomes."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug approved for diabetes and obesity could fail in Alzheimer's.", "prompt": "What's the best answer?", "options": ["One disease says little about another", "The trial was far too small to tell", "The drug was never tested in people"], "correctIndex": 0, "consequences": ["Brain drugs fail most of the time, whatever their record elsewhere.", "It enrolled 3,808 people over two years.", "It was tested in two Phase 3 trials."], "explanation": "Each disease has its own biology and its own odds. In Alzheimer's, most drugs fail."}, "proReasoning": "Explain trial failures with base rates. Most brain drugs fail, so a famous name does not change the odds much.", "commonMistake": "Assuming success in one disease carries over to the brain.", "mentalModel": "Every disease has its own odds."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$951f48ce-820b-5cc5-8c46-a005745e3ca8$ml$::uuid, $ml$neuroscience$ml$, 5, 2, $ml${"id": "neuroscience-d5-c2", "title": "The barrier and the odds", "lessonTitle": "Why brain drugs fail so often", "slot": 2, "type": "connect", "brief": {"headline": "Neurology drugs entering Phase 1 had a 5.9% chance of approval in 2011 to 2020, below the 7.9% average. Brain drugs also face a gate most others do not: the blood-brain barrier.", "kicker": "Connect day 3 and day 5: one gate behind the long odds.", "fullText": "On day 5 you saw the odds: a BIO study found neurology drugs entering Phase 1 from 2011 to 2020 had a 5.9% chance of approval, against 7.9% across all diseases. Alzheimer's drug development failed 99.6% of the time from 2002 to 2012.\n\nOn day 3 you met one reason brain drugs start behind. Pardridge called the blood-brain barrier the bottleneck in brain drug development: more than 98% of small-molecule drugs and essentially all large ones do not cross it. A drug that cannot reach its target cannot work, however good the target.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}, {"url": "https://www.fiercebiotech.com/r-d/alzheimer-s-r-d-suffers-as-trial-failure-rate-hits-an-astounding-99-6", "label": "FierceBiotech, Alzheimer's trial failure rate hits 99.6%"}, {"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how the barrier can sink a promising brain drug.", "steps": ["A drug works on its target in a dish", "In a patient, it enters the blood", "It meets the blood-brain barrier", "Too little of it reaches brain tissue", "The trial fails to show a benefit"], "explanation": "A dish has no barrier. In a body, the barrier can keep the drug from its target, and the trial fails."}, "numbers": {"kind": "numberSense", "prompt": "At 5.9% odds, about how many of 1,000 neurology drugs entering Phase 1 would win approval?", "min": 0, "max": 200, "value": 59, "unit": "drugs", "explanation": "About 59 of 1,000. At the 7.9% average it would be about 79."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a neurology biotech. They ask why brain drugs fail more often than others.", "prompt": "Which answer shows depth?", "options": ["The FDA rejects brain drugs on principle", "Many never get past the barrier", "Brain researchers are less skilled"], "correctIndex": 1, "consequences": ["The FDA gave Leqembi traditional approval in 2023.", "Over 98% of small molecules are blocked, a hurdle most fields lack.", "Nothing supports that; the biology is harder."], "explanation": "The barrier blocks most drugs before they reach brain tissue. It is a concrete reason for lower odds."}, "proReasoning": "Connect the base rate to a mechanism. Saying the barrier blocks most drugs explains part of neurology's lower odds.", "commonMistake": "Blaming people or regulators for a biological problem.", "mentalModel": "Explain odds with mechanisms.", "sources": [{"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "invest": {"call": {"kind": "theCall", "situation": "Two neurology biotechs pitch you. One has proof its drug reaches brain tissue; the other only dish data.", "prompt": "Which deserves better odds?", "options": ["The one with stronger dish results", "Both equal, since all start at 5.9%", "The one with proof of brain entry"], "correctIndex": 2, "consequences": ["A dish has no barrier, so it cannot test entry.", "Averages are a start; evidence about the barrier should shift them.", "It has passed a gate that blocks most brain drugs."], "explanation": "Base rates are where you start. Evidence that a drug gets in should move your estimate."}, "proReasoning": "Investors adjust base rates with specific evidence. Proof of brain entry removes one of the main reasons brain drugs fail.", "commonMistake": "Applying the average odds to every drug without adjusting.", "mentalModel": "Start with the base rate, then adjust."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're founding a company to help brain drugs reach their target. A friend says the market is too niche.", "prompt": "What's your best reply?", "options": ["Nearly every brain drug faces the barrier", "Only a few drugs ever need the brain", "The barrier only affects old drugs"], "correctIndex": 0, "consequences": ["Over 98% of small molecules and nearly all large ones are blocked.", "Every drug for a brain disease must reach the brain.", "The barrier blocks new and old drugs alike."], "explanation": "A problem shared by almost every brain drug is the opposite of niche."}, "proReasoning": "Founders size a delivery problem by how many drugs it blocks. Here, nearly all of them.", "commonMistake": "Seeing a platform problem as a niche one.", "mentalModel": "A shared gate is a big market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Alzheimer's drug trials failed 99.6% of the time from 2002 to 2012.", "prompt": "What's one clear reason?", "options": ["Alzheimer's has too few patients to test", "Many drugs struggle to get into the brain", "Researchers stopped testing new ideas"], "correctIndex": 1, "consequences": ["Alzheimer's is common, so patients were not the problem.", "The barrier blocks most drugs before they reach brain tissue.", "Programs kept coming in that decade; most failed."], "explanation": "The blood-brain barrier is one concrete reason. Most drugs never reach brain tissue in useful amounts."}, "proReasoning": "Give one mechanism, not a mystery. The barrier is a concrete reason brain drugs fail more often.", "commonMistake": "Treating brain drug failure as bad luck.", "mentalModel": "Failures have mechanisms."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0a1cacab-d178-5baf-8ba0-5080b49a4fe9$ml$::uuid, $ml$neuroscience$ml$, 5, 3, $ml${"id": "neuroscience-d5-c3", "title": "One drug, 5.9% odds", "lessonTitle": "Why brain drugs fail so often", "slot": 3, "type": "decide", "brief": {"headline": "You run a biotech with one drug: an Alzheimer's candidate entering Phase 1. Neurology drugs at that stage had a 5.9% chance of approval in 2011 to 2020.", "kicker": "Decide how to plan around odds this long.", "fullText": "You run a young biotech built around a single drug for Alzheimer's disease, about to enter Phase 1. The BIO study of 2011 to 2020 gives neurology drugs at this stage a 5.9% chance of reaching approval, against 7.9% across all diseases. In Alzheimer's, 99.6% of programs failed from 2002 to 2012.\n\nWinners exist. Leqembi, from Eisai and Biogen, won traditional FDA approval on July 6, 2023, after slowing clinical decline by 27% against placebo over 18 months. Its label carries a boxed warning for ARIA, brain scan changes such as swelling or bleeding. Even a success slows the disease rather than stopping it.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, Clinical Development Success Rates 2011 to 2020"}, {"url": "https://www.fiercebiotech.com/r-d/alzheimer-s-r-d-suffers-as-trial-failure-rate-hits-an-astounding-99-6", "label": "FierceBiotech, Alzheimer's trial failure rate hits 99.6%"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setup better survives a failed first trial?", "left": {"name": "One drug, all the cash", "note": "Every dollar rides on one Phase 1 result"}, "right": {"name": "Two programs, shared costs", "note": "A second bet keeps the company going"}, "correctIndex": 1, "explanation": "With 5.9% odds, most single bets fail. A second, independent program keeps the company alive when one does."}, "numbers": {"kind": "numberSense", "prompt": "At 5.9% odds, about how many of 100 neurology drugs entering Phase 1 fail to win approval?", "min": 0, "max": 100, "value": 94, "unit": "drugs", "explanation": "About 94 of 100. Failure is the base case, so plan for it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "This biotech offers you a senior role with a lot of stock.", "prompt": "What should you ask before saying yes?", "options": ["How quickly can the drug launch?", "How big is the Alzheimer's market?", "What happens to us if Phase 1 fails?"], "correctIndex": 2, "consequences": ["Most drugs never reach launch at all.", "Market size matters little if the drug fails.", "With 5.9% odds, the failure plan decides your job."], "explanation": "In a one-drug company, the stock is worth a lot only in the rare case the drug works. Ask about the plan for the common case."}, "proReasoning": "In a one-drug company, ask about the plan for failure first. Stock is worth a lot only in the rare case it works.", "commonMistake": "Valuing the stock as if approval were likely.", "mentalModel": "Price in the odds."}, "invest": {"call": {"kind": "theCall", "situation": "You could put your whole neurology budget into this company's next round.", "prompt": "What's the sound approach?", "options": ["Spread the money across several bets", "Go all in, since Leqembi succeeded", "Wait for approval before investing"], "correctIndex": 0, "consequences": ["With 5.9% odds, one result can wipe out a single bet.", "One success does not change the base rate.", "Waiting removes the risk and most of the reward with it."], "explanation": "Single trials decide everything in neurology. Several bets protect you from one failure."}, "proReasoning": "Investors in neurology spread risk because single trials decide everything. Several bets at 5.9% beat one.", "commonMistake": "Concentrating on one drug because another drug won.", "mentalModel": "Spread out binary risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "As founder, you can license a second, unrelated drug to run alongside your Alzheimer's candidate.", "prompt": "Why might that be worth the cost?", "options": ["Investors dislike focused companies", "It lowers the risk of total failure", "It doubles the first drug's odds"], "correctIndex": 1, "consequences": ["Many investors like focus; the point here is survival.", "With odds this long, two independent bets protect the company.", "Each drug keeps its own odds."], "explanation": "One failure should not end the company. A second program buys another chance."}, "proReasoning": "Founders in neurology often add a second program so one failure isn't fatal. Focus is good; a single point of failure is not.", "commonMistake": "Betting the company on one trial in a field where most trials fail.", "mentalModel": "Never just one shot."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears Leqembi was approved and assumes Alzheimer's drugs now usually work.", "prompt": "What's the fair picture?", "options": ["Most Alzheimer's drugs now succeed", "Leqembi stops the disease", "Successes are rare and partial"], "correctIndex": 2, "consequences": ["The failure rate was 99.6% from 2002 to 2012.", "It slows decline; it does not stop it.", "Leqembi slowed decline by 27%; most candidates fail."], "explanation": "One approval is news because most drugs fail. And it slows the disease rather than stopping it."}, "proReasoning": "Pair any success story with the base rate. One approval is news precisely because most drugs fail.", "commonMistake": "Reading one approval as a trend.", "mentalModel": "One win, many losses."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$06205f66-218a-53d2-9f3c-32d2b61f5673$ml$::uuid, $ml$neuroscience$ml$, 6, 1, $ml${"id": "neuroscience-d6-c1", "title": "A five-second stroke drug", "lessonTitle": "When blood stops reaching the brain", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025, the FDA approved tenecteplase for ischemic stroke, given as one five-second injection. The older drug, alteplase, needs a bolus plus a 60-minute infusion.", "kicker": "Apply time is brain: what does a simpler drug save?", "fullText": "Genentech's TNKase, tenecteplase, was approved on March 3, 2025, for adults with acute ischemic stroke, to be given within 3 hours of symptom onset. It was the first FDA-approved stroke medicine in nearly 30 years. In the AcT trial of about 1,600 patients at 22 Canadian stroke sites, 36.9% on tenecteplase and 34.8% on alteplase reached the best functional outcomes at 90 to 120 days, and bleeding rates were similar.\n\nThe difference is in the giving: one bolus replaces an hour-long infusion. When a New Zealand stroke network switched in 2020, its median door-to-needle time fell from 61 to 53 minutes, which the authors linked to more patients treated right in the CT scanner. That study was observational.", "sources": [{"url": "https://www.hcplive.com/view/fda-approves-tenecteplase-tnkase-for-acute-ischemic-stroke", "label": "HCPLive, FDA approves tenecteplase for acute ischemic stroke, Mar 2025"}, {"url": "https://www.tctmd.com/news/switching-tenecteplase-stroke-thrombolysis-may-boost-outcomes", "label": "TCTMD, Switching to tenecteplase for stroke may boost outcomes, Sep 2021"}]}, "evidence": {"kind": "faceOff", "prompt": "After switching, a New Zealand network cut its median door-to-needle time. Which drug did it switch to?", "left": {"name": "Tenecteplase", "note": "One bolus, about 5 seconds"}, "right": {"name": "Alteplase", "note": "Bolus plus a 60-minute infusion"}, "correctIndex": 0, "explanation": "After the switch to tenecteplase, the median fell from 61 to 53 minutes, with more patients treated in the scanner."}, "numbers": {"kind": "numberSense", "prompt": "At about 1.9 million neurons a minute, how many million neurons do 8 minutes represent in a large untreated stroke?", "min": 0, "max": 40, "value": 15, "unit": "M", "explanation": "8 times 1.9 million is about 15 million neurons. Minutes saved are brain saved."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a stroke network's quality team as it weighs switching to tenecteplase.", "prompt": "Which measure should you track first?", "options": ["Patient satisfaction scores", "Door-to-needle time", "Number of vials in stock"], "correctIndex": 1, "consequences": ["Worth tracking, but speed is what saves brain.", "Each minute costs about 1.9 million neurons in a large stroke.", "Stock matters, but it does not measure speed to treatment."], "explanation": "A simpler drug is worth what it does to the clock. Door-to-needle time measures that directly."}, "proReasoning": "Stroke teams judge changes by minutes saved to treatment. A simpler drug is worth what it does to that clock.", "commonMistake": "Measuring a stroke change by convenience instead of time.", "mentalModel": "Measure the minutes.", "sources": [{"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "invest": {"call": {"kind": "theCall", "situation": "TNKase wins FDA approval for stroke. Its trial showed outcomes close to alteplase.", "prompt": "What's its main selling point to hospitals?", "options": ["Far better outcomes than alteplase", "No bleeding risk at all", "Similar results with a much simpler dose"], "correctIndex": 2, "consequences": ["AcT showed 36.9% against 34.8%, a non-inferiority result.", "Bleeding is among its most common adverse reactions.", "One bolus replaces an hour-long infusion with comparable results."], "explanation": "AcT was a non-inferiority trial. The case for switching is speed and simplicity, not a big jump in outcomes."}, "proReasoning": "Investors read a non-inferiority win as a convenience story. Its value depends on whether hospitals switch for speed and simplicity.", "commonMistake": "Reading approval as proof of superior outcomes.", "mentalModel": "Same outcome, simpler workflow."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes stroke workflow software. Hospitals are switching to tenecteplase.", "prompt": "Where should your product focus?", "options": ["Cutting minutes before the needle", "Managing hour-long infusion pumps", "Billing for alteplase infusions"], "correctIndex": 0, "consequences": ["With a five-second bolus, the remaining delays come before treatment.", "The infusion step is shrinking to one injection.", "Hospitals switching drugs are leaving that workflow."], "explanation": "When the drug takes seconds to give, the delays left are the ones before it. Build there."}, "proReasoning": "When one step shrinks, founders move to the next bottleneck. With the drug given in seconds, delays before the needle matter most.", "commonMistake": "Building for the step that just got faster.", "mentalModel": "Chase the next bottleneck."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a stroke drug that works about as well as the old one is a big deal.", "prompt": "What's the best answer?", "options": ["It can be taken at home as a pill", "It is faster to give, and time is brain", "It works twice as well"], "correctIndex": 1, "consequences": ["It is a single injection into a vein.", "A five-second bolus can help teams start treatment sooner.", "Results were similar: 36.9% against 34.8%."], "explanation": "In stroke, every minute costs neurons. A drug that is quicker to give can save minutes."}, "proReasoning": "In stroke, speed counts as much as potency. A drug that is easier to give can save brain by saving minutes.", "commonMistake": "Judging a stroke drug only by its trial outcome.", "mentalModel": "In stroke, speed is a feature."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$4c5ba371-c1de-5be2-b7f7-1d0983a600c0$ml$::uuid, $ml$neuroscience$ml$, 6, 2, $ml${"id": "neuroscience-d6-c2", "title": "A hungry organ cannot wait", "lessonTitle": "When blood stops reaching the brain", "slot": 2, "type": "connect", "brief": {"headline": "The brain uses about 20% of the body's resting energy. When a large ischemic stroke goes untreated, it loses about 1.9 million neurons every minute.", "kicker": "Connect day 4 and day 6: a hungry organ can't wait.", "fullText": "On day 4 you learned the brain is about 2% of body weight yet uses about 20% of resting energy, and holds about 86 billion neurons. On day 6 you saw what happens when its blood supply stops. About 87% of strokes are ischemic, caused by a blocked vessel. In a typical large untreated ischemic stroke, Saver estimated the brain loses about 1.9 million neurons and 14 billion synapses each minute, aging about 3.6 years for each hour.\n\nAn organ that burns that much energy has little to fall back on. When a vessel blocks, the region it feeds starts dying within minutes.", "sources": [{"url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108621", "label": "BioNumbers, brain share of resting metabolism"}, {"url": "https://Gwern.net/doc/psychology/neuroscience/2009-azevedo.pdf", "label": "Azevedo et al. 2009, neuron counts in the human brain"}, {"url": "https://www.cdc.gov/stroke/data-research/facts-stats/index.html", "label": "CDC, Stroke facts"}, {"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow what happens when a vessel to the brain blocks.", "steps": ["A blood vessel to the brain blocks", "The region it feeds loses its blood supply", "Energy-hungry neurons run out of fuel", "About 1.9 million neurons die each minute", "Lost function shows up as disability"], "explanation": "The brain needs a steady supply of energy. Without blood, the region starts dying within minutes."}, "numbers": {"kind": "numberSense", "prompt": "At 1.9 million neurons a minute, about how many million neurons does one hour without treatment cost?", "min": 0, "max": 300, "value": 114, "unit": "M", "explanation": "60 times 1.9 million is about 114 million neurons in an hour, along with about 3.6 years of brain aging."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a stroke program manager role. They ask why speed matters so much.", "prompt": "What's your strongest answer?", "options": ["Patients dislike waiting in hospitals", "Fast care lowers hospital paperwork", "About 1.9 million neurons die each minute"], "correctIndex": 2, "consequences": ["True, but it misses the biology.", "Paperwork is not why minutes matter.", "A number ties speed directly to brain saved."], "explanation": "The brain burns energy fast and dies fast without blood. One number makes the case."}, "proReasoning": "Tie stroke speed to the biology: an energy-hungry organ loses about 1.9 million neurons a minute without blood.", "commonMistake": "Explaining stroke urgency as a service issue.", "mentalModel": "Minutes are neurons."}, "invest": {"call": {"kind": "theCall", "situation": "A stroke startup claims its product saves 10 minutes per patient.", "prompt": "How can you put a number on that?", "options": ["Roughly 19 million neurons", "About 10 neurons saved per patient", "It cannot be measured in any way"], "correctIndex": 0, "consequences": ["10 minutes at 1.9 million a minute is about 19 million.", "Off by a factor of millions.", "Saver's estimate gives a way to measure it."], "explanation": "Saver's estimate turns minutes into neurons, so time claims can be compared."}, "proReasoning": "Investors turn a time claim into an outcome number. Saver's estimate makes minutes comparable.", "commonMistake": "Accepting time savings without asking what they are worth.", "mentalModel": "Convert minutes into brain."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a stroke alert app. You can show one fact on its home screen.", "prompt": "Which fact best explains your mission?", "options": ["The brain holds 86 billion neurons", "1.9 million neurons lost each minute", "The brain is 2% of body weight"], "correctIndex": 1, "consequences": ["True, but it says nothing about urgency.", "It ties your product's speed to brain saved.", "Weight is the misleading number."], "explanation": "Your product sells speed. The cost of each minute is the number that makes speed matter."}, "proReasoning": "Founders pick the number that makes their value obvious. For a stroke alert, that is the cost of each minute.", "commonMistake": "Leading with a general brain fact instead of the urgent one.", "mentalModel": "Lead with the number that sets the clock."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why doctors say 'time is brain' about strokes.", "prompt": "What's the clearest explanation?", "options": ["Strokes spread like an infection", "Lost neurons are replaced in minutes", "Without blood, the brain dies fast"], "correctIndex": 2, "consequences": ["A blocked vessel starves a region; it is not an infection.", "Nothing replaces 1.9 million neurons a minute.", "It uses about 20% of resting energy and loses 1.9 million neurons a minute."], "explanation": "The brain needs a lot of energy and has little reserve. Without blood, neurons die by the million each minute."}, "proReasoning": "Explain time is brain with two numbers: the energy the brain needs and the neurons lost each minute without it.", "commonMistake": "Thinking stroke damage happens all at once.", "mentalModel": "No blood, no energy, lost neurons."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f3f9b737-cf61-5b35-8d02-ba27498f0c44$ml$::uuid, $ml$neuroscience$ml$, 6, 3, $ml${"id": "neuroscience-d6-c3", "title": "Which stroke to build for", "lessonTitle": "When blood stops reaching the brain", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup choosing its first stroke product. Of the more than 795,000 US strokes each year, about 87% are ischemic, caused by a blocked vessel.", "kicker": "Decide where a new stroke company should start.", "fullText": "You run a young medtech startup with money for one stroke product. More than 795,000 people in the US have a stroke each year, and about 87% are ischemic, caused by a blocked vessel to the brain. Stroke is a leading cause of serious long-term disability, and it cost the US nearly $56.2 billion in 2019 to 2020.\n\nTime sets the stakes. In a typical large untreated ischemic stroke, Saver estimated the brain loses about 1.9 million neurons each minute. Your choice: where in that story can one product make the biggest difference?", "sources": [{"url": "https://www.cdc.gov/stroke/data-research/facts-stats/index.html", "label": "CDC, Stroke facts"}, {"url": "https://pubmed.ncbi.nlm.nih.gov/16339467/", "label": "Saver, Time is brain quantified, Stroke 2006"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact support starting with ischemic stroke and speed?", "buckets": ["Supports it", "Doesn't bear on it"], "items": [{"text": "About 87% of strokes are ischemic", "bucket": 0}, {"text": "About 1.9 million neurons are lost each minute", "bucket": 0}, {"text": "More than 795,000 US strokes a year", "bucket": 0}, {"text": "The brain is about 2% of body weight", "bucket": 1}, {"text": "The cortex holds about 19% of neurons", "bucket": 1}], "explanation": "Patient numbers and the cost of each minute point to ischemic stroke and speed. General brain facts do not decide it."}, "numbers": {"kind": "numberSense", "prompt": "About 87% of more than 795,000 yearly US strokes are ischemic. About how many thousand is that?", "min": 0, "max": 1000, "value": 692, "unit": "K", "explanation": "87% of 795,000 is about 692,000 people a year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's first clinical lead. The CEO asks where minutes are lost before treatment.", "prompt": "How do you find out?", "options": ["Map each step from symptoms to treatment", "Ask investors which step they like", "Assume the hospital is the slow part"], "correctIndex": 0, "consequences": ["Mapping the steps shows where the minutes, and neurons, go.", "Investors do not see where minutes go.", "Guessing skips the evidence you need."], "explanation": "Every step from first symptom to treatment costs neurons. Measure the whole path before choosing a fix."}, "proReasoning": "Clinical leads measure the whole path before picking a fix. In stroke, every step from first symptom to treatment costs neurons.", "commonMistake": "Picking a fix before mapping the delays.", "mentalModel": "Map the clock before fixing it."}, "invest": {"call": {"kind": "theCall", "situation": "The startup pitches you a product to speed care for ischemic stroke.", "prompt": "Which fact best supports the market size?", "options": ["The cerebellum holds 80% of neurons", "About 87% of 795,000 strokes are ischemic", "The brain uses 20% of resting energy"], "correctIndex": 1, "consequences": ["True, but it has nothing to do with stroke demand.", "That is roughly 692,000 people a year in the US.", "True, but it does not size a market."], "explanation": "Market size starts with patients. Ischemic stroke is most of all strokes."}, "proReasoning": "Investors size the market from the patients a product can reach. Ischemic stroke is most of all strokes.", "commonMistake": "Using a striking brain fact in place of a patient count.", "mentalModel": "Size it by patients."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cofounder wants to start with the other 13% of strokes, where there is less competition.", "prompt": "What's the strongest case for ischemic first?", "options": ["It needs no regulatory approval", "It has no competitors at all", "It covers about 87% of patients"], "correctIndex": 2, "consequences": ["Medical products for stroke still need regulators.", "Treatments already exist, so you must beat them.", "Most patients have this type, so your product reaches more people."], "explanation": "Starting where most patients are gives a first product the widest use."}, "proReasoning": "Founders weigh reach against competition. Starting where 87% of patients are gives a product the widest use.", "commonMistake": "Choosing a smaller group only to avoid rivals.", "mentalModel": "Start where most patients are."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what 'ischemic' means in a stroke news story.", "prompt": "What do you say?", "options": ["A blocked vessel cuts blood to the brain", "A stroke caused mainly by stress", "A stroke that always heals by itself"], "correctIndex": 0, "consequences": ["About 87% of strokes are this type.", "Ischemic means blood flow is blocked.", "Untreated, neurons die by the minute."], "explanation": "Ischemic means blood flow to part of the brain is blocked. It is the most common kind of stroke."}, "proReasoning": "Explain medical words by what happens: ischemic means blood flow to part of the brain is blocked.", "commonMistake": "Using the term without saying what it means.", "mentalModel": "Name it by what happens."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$13d38de5-7104-5aad-aee5-5ce53b08d3ff$ml$::uuid, $ml$neuroscience$ml$, 7, 1, $ml${"id": "neuroscience-d7-c1", "title": "A pill that boosts the brakes", "lessonTitle": "The chemicals neurons use to talk", "slot": 1, "type": "apply", "brief": {"headline": "In August 2023, the FDA approved zuranolone, the first pill for postpartum depression. It acts on GABA-A receptors, part of the brain's main inhibitory system, not on serotonin or dopamine.", "kicker": "Apply the messengers: a depression drug that works through GABA.", "fullText": "Zurzuvae, or zuranolone, was approved on August 4, 2023, as the first oral treatment for postpartum depression in adults. It is taken once a day for 14 days. In two placebo-controlled studies, patients improved more than on placebo by day 15, and the effect lasted through four weeks of follow-up.\n\nIt is a neuroactive steroid that acts on GABA-A receptors. Unlike standard antidepressants, it does not act directly on serotonin or dopamine. The only earlier approved drug for postpartum depression, brexanolone, works the same way but needs a 60-hour continuous IV infusion in a hospital.\n\nThe FDA did not approve zuranolone for major depressive disorder. A different messenger target opened a new option for one condition, not for all depression.", "sources": [{"url": "https://psychiatrictimes.com/view/fda-approves-first-oral-treatment-for-postpartum-depression-in-adults", "label": "Psychiatric Times, FDA approves first oral treatment for postpartum depression, Aug 2023"}, {"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}]}, "evidence": {"kind": "faceOff", "prompt": "Both drugs act on GABA-A receptors. Which one can be taken at home?", "left": {"name": "Zuranolone", "note": "One pill a day for 14 days"}, "right": {"name": "Brexanolone", "note": "60-hour IV infusion in a hospital"}, "correctIndex": 0, "explanation": "Same messenger target, very different delivery. Zuranolone moved the treatment from a hospital bed to a pill at home."}, "numbers": {"kind": "numberSense", "prompt": "Brexanolone needs a 60-hour continuous infusion. How many days of round-the-clock treatment is that?", "min": 0, "max": 7, "value": 2.5, "unit": "days", "explanation": "60 hours is two and a half days in a hospital, against a 14-day course of pills at home."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a medical affairs role on a GABA-based depression drug.", "prompt": "How do you explain what makes it different?", "options": ["It is a stronger serotonin booster", "It works by exciting glutamate signals", "It works through GABA, not serotonin"], "correctIndex": 2, "consequences": ["It does not act directly on serotonin or dopamine.", "Glutamate is the excitatory messenger; this drug targets GABA.", "It acts on GABA-A receptors, part of the main inhibitory system."], "explanation": "Zuranolone acts on GABA-A receptors rather than on serotonin or dopamine. That is its story in one line."}, "proReasoning": "Name the messenger system a drug targets and how that differs from the standard. It shows you understand why the drug exists.", "commonMistake": "Assuming every depression drug works through serotonin.", "mentalModel": "Name the messenger first."}, "invest": {"call": {"kind": "theCall", "situation": "Zuranolone wins approval for postpartum depression but not for major depressive disorder.", "prompt": "How should that shape your view of its market?", "options": ["A narrower group than all depression", "The whole depression market is open", "The approval is worthless without MDD"], "correctIndex": 0, "consequences": ["Postpartum depression is one condition, not all depression.", "The FDA did not approve it for major depressive disorder.", "A first oral option for postpartum depression still has value."], "explanation": "The approved use defines who can be treated. A broad mechanism does not mean a broad label."}, "proReasoning": "Investors read the label, not the mechanism's promise. The approved use defines the market.", "commonMistake": "Sizing a drug's market by the disease family instead of the label.", "mentalModel": "The label sets the market."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup supports new mothers. Zuranolone is a 14-day pill; the older option was a 60-hour hospital infusion.", "prompt": "What gap does the switch to a pill open?", "options": ["Selling the drug directly to mothers", "Support for treatment taken at home", "More hospital beds for long infusions"], "correctIndex": 1, "consequences": ["Startups can support care; prescribing stays with clinicians.", "A home course needs follow-up and support outside the hospital.", "The new pill moves treatment out of the hospital."], "explanation": "When treatment leaves the hospital, so does the support that came with it. That is the gap to fill."}, "proReasoning": "When treatment moves from hospital to home, founders look at what the hospital used to provide. Support and follow-up are the new gap.", "commonMistake": "Building for the old setting after the treatment has moved.", "mentalModel": "Follow where treatment moves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thought all depression drugs raise serotonin. You mention zuranolone.", "prompt": "What's the simplest explanation?", "options": ["It is simply a faster serotonin drug", "It shuts dopamine down completely", "It boosts the brain's main brake, GABA"], "correctIndex": 2, "consequences": ["It does not act directly on serotonin.", "It does not act directly on dopamine either.", "GABA is the most common inhibitory messenger."], "explanation": "Zuranolone works on GABA-A receptors. Mood drugs can work through the stop signal, not only serotonin."}, "proReasoning": "Explain messengers as go and stop signals. Some depression drugs adjust the stop signal instead of serotonin.", "commonMistake": "Thinking serotonin is the only lever on mood.", "mentalModel": "Brakes and accelerators."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$31f8c7f9-bea6-5d3a-b4b9-e07f97b7604b$ml$::uuid, $ml$neuroscience$ml$, 7, 2, $ml${"id": "neuroscience-d7-c2", "title": "To change a messenger, get in first", "lessonTitle": "The chemicals neurons use to talk", "slot": 2, "type": "connect", "brief": {"headline": "Brain drugs work by changing messenger systems such as glutamate, GABA, dopamine and serotonin. But more than 98% of small-molecule drugs cannot reach brain tissue.", "kicker": "Connect day 3 and day 7: the target sits behind the gate.", "fullText": "On day 7 you met the brain's chemical messengers: at least 100 of them, with glutamate the main excitatory signal, GABA the main inhibitory one, and dopamine and serotonin shaping reward, mood, sleep and appetite. Brain drugs work by changing these systems.\n\nOn day 3 you met the gate in front of them. Pardridge wrote that more than 98% of small-molecule drugs and essentially all large-molecule drugs do not cross the blood-brain barrier. Picking the right messenger is half the job. The drug also has to reach the neurons that use it.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}, {"url": "https://springeropen.altmetric.com/details/3182022", "label": "Pardridge 2005, The blood-brain barrier: bottleneck in brain drug development"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a messenger drug's journey in order.", "steps": ["Pick a messenger system to change", "Design a molecule that acts on it", "Get the molecule across the barrier", "It reaches the neurons it targets", "The messenger balance shifts"], "explanation": "The target comes first, but the barrier sits between the molecule and the neurons. Skip that step and nothing shifts."}, "numbers": {"kind": "numberSense", "prompt": "Scientists know of at least how many chemical messengers in the nervous system?", "min": 0, "max": 300, "value": 100, "unit": "messengers", "explanation": "At least 100. Plenty of targets, all behind the same barrier."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a company with a new GABA drug. They ask what you'd check first.", "prompt": "Which question shows depth?", "options": ["How does it get across the barrier?", "Is GABA really an inhibitory messenger?", "How many messengers exist in total?"], "correctIndex": 0, "consequences": ["Most drugs are blocked, so entry comes before effect.", "GABA is the most common inhibitory messenger; that is settled.", "At least 100, but the count does not test the drug."], "explanation": "The target is known. Whether the drug reaches it is the open question."}, "proReasoning": "Pair the target with the route. A good messenger target fails if the drug never reaches the brain.", "commonMistake": "Judging a brain drug by its target alone.", "mentalModel": "Target and route."}, "invest": {"call": {"kind": "theCall", "situation": "Two companies target the same messenger system. Only one has data showing its drug reaches the brain.", "prompt": "How should that weigh in your decision?", "options": ["Only if the drug is a large molecule", "Heavily, since it clears the first gate", "Not at all, since the target is what counts"], "correctIndex": 1, "consequences": ["Small molecules are blocked too, more than 98% of them.", "With over 98% of small molecules blocked, proof of entry is rare.", "A target the drug never reaches is useless."], "explanation": "Proof of entry separates a real candidate from a hopeful one, whatever the molecule size."}, "proReasoning": "Investors treat brain entry as a gate the target cannot skip. Evidence of entry separates real candidates from hopeful ones.", "commonMistake": "Assuming small molecules get in easily.", "mentalModel": "No entry, no effect."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team has a molecule that calms overactive neurons in a dish by boosting GABA.", "prompt": "What's the next question to answer?", "options": ["Which messenger should we target?", "Can we market it as a supplement?", "Does it reach brain tissue in animals?"], "correctIndex": 2, "consequences": ["You already picked GABA; now prove it gets there.", "That skips the evidence a brain drug needs.", "A dish has no barrier, so test entry next."], "explanation": "A dish result says the target works. Only an animal test says the drug gets there."}, "proReasoning": "Founders test the hardest gate early. For a messenger drug, brain entry comes right after the dish.", "commonMistake": "Moving to marketing before proving the drug reaches the brain.", "mentalModel": "Test the gate early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why you can't just swallow a calming messenger and send it to the brain.", "prompt": "What's a fair answer?", "options": ["Most molecules in blood can't reach the brain", "Calming messengers excite neurons instead", "The brain makes no messengers of its own"], "correctIndex": 0, "consequences": ["The blood-brain barrier keeps most molecules out of brain tissue.", "Inhibitory messengers like GABA tell neurons to stop.", "The brain makes its own, including glutamate and GABA."], "explanation": "The barrier blocks more than 98% of small-molecule drugs. Reaching the blood is not reaching the brain."}, "proReasoning": "Explain the barrier with an everyday example: what you swallow reaches your blood, but the brain is guarded.", "commonMistake": "Assuming anything in the blood reaches the brain.", "mentalModel": "Blood is not brain."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$b672d033-4a8d-5d1a-be7f-44978049eb47$ml$::uuid, $ml$neuroscience$ml$, 7, 3, $ml${"id": "neuroscience-d7-c3", "title": "Brake or accelerator", "lessonTitle": "The chemicals neurons use to talk", "slot": 3, "type": "decide", "brief": {"headline": "You run a small team designing a drug for seizures. Glutamate is the brain's main go signal, and GABA is its main stop signal, which helps regulate seizures.", "kicker": "Decide which messenger your seizure drug should push.", "fullText": "You run a drug discovery team with funding for one seizure program. Day 7 gives you the map of messengers. Glutamate is the most common excitatory neurotransmitter, passing signals on, and is key to learning and memory. GABA is the most common inhibitory one, blocking signals, and helps regulate anxiety, sleep and seizures.\n\nEvery signal is a balance of excitation and inhibition. Your choice is which side of that balance to push, and what else that push might touch.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Your drug must calm overactive signaling. Which change pushes the balance the right way?", "options": ["More excitation through glutamate", "More reward through dopamine", "More inhibition through GABA"], "correctIndex": 2, "explanation": "GABA blocks signals from passing on and helps regulate seizures. Adding excitation would push the wrong way."}, "numbers": {"kind": "numberSense", "prompt": "Your team screens 400 molecules. If over 98% cannot cross the barrier, fewer than how many might get in?", "min": 0, "max": 40, "value": 8, "unit": "molecules", "explanation": "Under 2% of 400 is under 8. A perfect GABA target still needs molecules that reach it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new scientist on the team. Your lead asks which effects to watch for with a GABA booster.", "prompt": "Which worry follows most logically?", "options": ["Higher motivation from more dopamine release", "Sleepiness, since GABA helps regulate sleep", "Sharper memory from extra glutamate signals"], "correctIndex": 1, "consequences": ["Dopamine is a different messenger system.", "GABA helps regulate anxiety, sleep and seizures, so expect overlap.", "A GABA drug pushes inhibition, not glutamate."], "explanation": "A messenger system runs several jobs. Pushing it for seizures can touch sleep and anxiety too."}, "proReasoning": "A messenger touches many jobs. Scientists predict side effects from the other jobs the same system runs.", "commonMistake": "Expecting a drug to change only the job you want.", "mentalModel": "One messenger, many jobs."}, "invest": {"call": {"kind": "theCall", "situation": "The team pitches a GABA-boosting seizure drug to your fund.", "prompt": "What should you ask about competition?", "options": ["Whether glutamate exists in mice", "How many neurons a brain holds", "Who else already targets GABA?"], "correctIndex": 2, "consequences": ["That has nothing to do with competition.", "True numbers, wrong question.", "Many brain drugs act on the same systems, so rivals may be close."], "explanation": "The target sets the competition. Drugs acting on the same messenger compete for the same patients."}, "proReasoning": "The target sets the competition. Investors check who else acts on the same messenger system before backing a new entry.", "commonMistake": "Assuming a target is open because the science is solid.", "mentalModel": "Same target, same rivals."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. A board member suggests blocking glutamate instead, to cut excitation directly.", "prompt": "What's the key risk to weigh?", "options": ["Glutamate also drives learning and memory", "Glutamate plays no part in excitation", "GABA and glutamate are the same thing"], "correctIndex": 0, "consequences": ["Turning down the go signal can touch memory too.", "It is the most common excitatory messenger.", "They are opposites: go and stop."], "explanation": "Glutamate is key to learning and memory. Cutting it to calm seizures has a cost to weigh."}, "proReasoning": "Founders weigh what else a target touches. Glutamate is key to learning and memory, so cutting it has a cost.", "commonMistake": "Picking a target by its main job and ignoring its others.", "mentalModel": "Know what else it touches."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a seizure drug can work by adding a stop signal.", "prompt": "What's the clearest answer?", "options": ["It raises dopamine to calm the brain", "It tips the balance toward inhibition", "It deletes the go signal entirely"], "correctIndex": 1, "consequences": ["Dopamine shapes reward and motivation, not braking.", "GABA tells neurons to stop passing signals on.", "The brain needs glutamate for learning and memory."], "explanation": "Every signal is a balance of go and stop. More stop can calm too much go."}, "proReasoning": "Explain brain chemistry as balance. Too much go, add stop; too much stop, add go.", "commonMistake": "Thinking of messengers as simply on or off.", "mentalModel": "Every signal is a balance."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$dd93b8ef-42e6-54f4-b1f1-5b10fca11cad$ml$::uuid, $ml$neuroscience$ml$, 8, 1, $ml${"id": "neuroscience-d8-c1", "title": "AbbVie's $8.7 billion miss", "lessonTitle": "A $14 billion bet on a new target", "slot": 1, "type": "apply", "brief": {"headline": "AbbVie paid $8.7 billion for Cerevel, betting on a new kind of schizophrenia drug. In November 2024, that drug, emraclidine, failed two Phase 2 trials, and AbbVie's shares fell 12%.", "kicker": "Apply the lesson: a new mechanism can be worth billions, or nothing.", "fullText": "Emraclidine targets the M4 muscarinic receptor alone. It was the centerpiece of AbbVie's $8.7 billion Cerevel deal, completed in August 2024. On November 11, 2024, AbbVie reported that neither EMPOWER-1 nor EMPOWER-2, Phase 2 trials with 372 patients in all, beat placebo on the PANSS symptom scale at week six. Analysts at Stifel pointed to a very high placebo response.\n\nAbbVie's shares fell 12% at the open, and Bristol Myers Squibb's rose more than 11%. BMS's Cobenfy, from its $14 billion Karuna deal, acts on both M1 and M4 receptors and had just been approved. Same new family of targets, opposite outcomes.", "sources": [{"url": "https://www.biospace.com/drug-development/abbvie-shares-plummet-12-as-cerevel-schizophrenia-asset-fails-phase-ii-trials", "label": "BioSpace, AbbVie shares plummet 12% as Cerevel schizophrenia asset fails Phase II, Nov 2024"}, {"url": "https://www.clinicaltrialsarena.com/news/abbvie-stock-plummets-over-12-after-schizophrenia-drug-flops-in-phase-ii-trials/", "label": "Clinical Trials Arena, AbbVie stock plummets after schizophrenia drug flops, Nov 2024"}, {"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which drug does each fact describe?", "buckets": ["Emraclidine", "Cobenfy"], "items": [{"text": "Targets the M4 receptor alone", "bucket": 0}, {"text": "Came with the Cerevel deal", "bucket": 0}, {"text": "Missed its main goal in two trials", "bucket": 0}, {"text": "Acts on M1 and M4 receptors", "bucket": 1}, {"text": "Came with a $14 billion deal", "bucket": 1}, {"text": "Approved by the FDA in 2024", "bucket": 1}], "explanation": "Both bet on muscarinic receptors. One reached approval; the other missed in Phase 2."}, "numbers": {"kind": "numberSense", "prompt": "AbbVie's shares fell from $199.50 to $174.80 at the open. By about what percent?", "min": 0, "max": 40, "value": 12, "unit": "%", "explanation": "A drop of $24.70, about 12%, on one trial readout."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You were about to join AbbVie's neuroscience unit when emraclidine failed in November 2024.", "prompt": "What's the smart question to ask now?", "options": ["What else is in the neuroscience pipeline?", "Will my desk move to a different floor now?", "Will the drug still be approved anyway?"], "correctIndex": 0, "consequences": ["With the flagship gone, the rest of the pipeline carries the unit.", "Desks matter less than what the team now works on.", "It missed its main goal in both trials."], "explanation": "After a flagship failure, your role depends on what the unit still has to work on."}, "proReasoning": "After a flagship failure, ask what the unit works on next. Your role depends on the remaining pipeline.", "commonMistake": "Assuming a big company protects every program.", "mentalModel": "Ask what's left in the pipeline."}, "invest": {"call": {"kind": "theCall", "situation": "On November 11, 2024, AbbVie falls 12% and BMS rises over 11% on the same news.", "prompt": "Why did BMS rise?", "options": ["Emraclidine was licensed to BMS", "A rival to its new drug just stumbled", "BMS bought AbbVie that morning"], "correctIndex": 1, "consequences": ["Emraclidine was AbbVie's, from Cerevel.", "Cobenfy now faced one less close muscarinic rival.", "No such deal happened."], "explanation": "In a new drug class, a rival's failure can strengthen the leader. Analysts called it a clearer win for Bristol."}, "proReasoning": "Investors read a rival's failure as news for the survivor. In a new mechanism class, one stumble can widen the leader's lead.", "commonMistake": "Reading a trial result as news for one company only.", "mentalModel": "A rival's miss is your gain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has an M4-only drug in early development. Emraclidine just failed with a high placebo response.", "prompt": "What should you change in your trial plan?", "options": ["Drop all muscarinic research at once", "Skip Phase 2 to save time", "Design to control placebo response"], "correctIndex": 2, "consequences": ["Cobenfy, acting on M1 and M4, was approved.", "Skipping steps risks a bigger, costlier failure.", "Stifel pointed to a very high placebo response in the failed trials."], "explanation": "Learn from the rival's trial before repeating it. Placebo response can sink a drug that might work."}, "proReasoning": "Founders learn from a rival's failure before repeating it. Trial design, like placebo control, can decide a result.", "commonMistake": "Abandoning a mechanism class after one rival fails.", "mentalModel": "Learn from the rival's miss."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how two drugs aimed at the same receptor family could end so differently.", "prompt": "What's a fair answer?", "options": ["Different receptors, different trials", "One company simply got luckier", "The FDA simply prefers BMS drugs"], "correctIndex": 0, "consequences": ["Cobenfy acts on M1 and M4; emraclidine on M4 alone.", "Luck plays a part, but the drugs differ too.", "Emraclidine failed its own trials before any FDA review."], "explanation": "Same family, different receptors and different trials. Real differences come before luck."}, "proReasoning": "Explain divergent results by real differences first: which receptors, which trials. Luck is the last resort.", "commonMistake": "Treating a drug family as one drug.", "mentalModel": "Same family, different drugs."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a3151dd8-dfb2-53ee-9ce7-8b27df0c84fb$ml$::uuid, $ml$neuroscience$ml$, 8, 2, $ml${"id": "neuroscience-d8-c2", "title": "Beyond dopamine", "lessonTitle": "A $14 billion bet on a new target", "slot": 2, "type": "connect", "brief": {"headline": "Dopamine shapes reward, motivation and learning, and schizophrenia drugs long relied on it. Cobenfy, approved in 2024, works through cholinergic muscarinic receptors instead.", "kicker": "Connect day 7 and day 8: a different messenger, a new class.", "fullText": "On day 7 you saw that scientists know at least 100 chemical messengers, and that dopamine plays a role in reward, motivation and learning. On day 8 you met Cobenfy, approved on September 26, 2024, for schizophrenia. The FDA called it the first antipsychotic to target cholinergic receptors as opposed to dopamine receptors. It acts on muscarinic M1 and M4 receptors.\n\nWith so many messengers, a drug that moves to a different one can open a new class. That is what Bristol Myers Squibb paid about $14 billion for when it bought Karuna.", "sources": [{"url": "https://my.clevelandclinic.org/health/articles/22513-neurotransmitters", "label": "Cleveland Clinic, Neurotransmitters"}, {"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What made Cobenfy a first among antipsychotics?", "options": ["It targets cholinergic, not dopamine, receptors", "It was the very first pill for schizophrenia", "It sharply raises dopamine levels in the brain"], "correctIndex": 0, "explanation": "The FDA called it the first antipsychotic targeting cholinergic receptors as opposed to dopamine receptors."}, "numbers": {"kind": "numberSense", "prompt": "BMS paid about $14 billion. At about $22,500 a year, how many thousand patient-years at list price would match that?", "min": 0, "max": 1000, "value": 622, "unit": "K", "explanation": "$14 billion divided by $22,500 is about 622,000 patient-years, before any costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at BMS, you're asked why Cobenfy matters scientifically.", "prompt": "What's the best answer?", "options": ["It works through serotonin alone", "It skips dopamine to treat psychosis", "It is a cheaper dopamine blocker"], "correctIndex": 1, "consequences": ["Its targets are cholinergic muscarinic receptors.", "It acts on muscarinic M1 and M4 receptors.", "It does not target dopamine receptors."], "explanation": "Its novelty is the messenger: muscarinic receptors instead of dopamine."}, "proReasoning": "Name the messenger shift: from dopamine to muscarinic receptors. That is why the drug was a first.", "commonMistake": "Describing a new class in terms of the old one.", "mentalModel": "Name the new messenger."}, "invest": {"call": {"kind": "theCall", "situation": "After Cobenfy, a biotech pitches you another schizophrenia drug that targets dopamine.", "prompt": "What should you probe?", "options": ["Whether dopamine exists in humans", "Whether BMS will pay $14 billion for it", "How it beats existing dopamine drugs"], "correctIndex": 2, "consequences": ["Dopamine shapes reward and motivation; that is settled.", "The Karuna price came from a new mechanism.", "Schizophrenia drugs long relied on dopamine, so the field is crowded."], "explanation": "A new messenger earned the premium. Another dopamine drug must prove an edge over many."}, "proReasoning": "Investors ask how a drug differs from what exists. A new messenger earned $14 billion; another dopamine drug must prove an edge.", "commonMistake": "Expecting any schizophrenia drug to fetch a Karuna price.", "mentalModel": "Novelty earns the premium."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are picking a target for a new psychiatric drug. Your advisor says to look beyond dopamine and serotonin.", "prompt": "What makes that advice sound?", "options": ["There are at least 100 messengers", "Dopamine and serotonin do nothing", "Muscarinic targets are now banned"], "correctIndex": 0, "consequences": ["With so many, less-used systems may hold new classes, as Cobenfy did.", "They shape reward and mood; they are just crowded.", "Cobenfy, a muscarinic drug, was approved in 2024."], "explanation": "Cobenfy showed that moving to a different messenger can open a new class."}, "proReasoning": "Founders look where few drugs act. Cobenfy showed a messenger system outside dopamine can open a new class.", "commonMistake": "Assuming the well-known systems are the only ones that matter.", "mentalModel": "Look past the crowded targets."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says all antipsychotics work the same way.", "prompt": "What's a good reply?", "options": ["Yes, they all raise dopamine in the brain", "Cobenfy acts on muscarinic receptors", "Yes, they all block serotonin the same way"], "correctIndex": 1, "consequences": ["Older antipsychotics relied on dopamine; Cobenfy does not.", "It was the first to target cholinergic, not dopamine, receptors.", "Older ones relied on dopamine; Cobenfy differs."], "explanation": "Cobenfy works through a different messenger system, so antipsychotics are not all alike."}, "proReasoning": "Use one counterexample to break a generalization. Cobenfy shows antipsychotics can work through another messenger.", "commonMistake": "Assuming a drug class is defined by one mechanism forever.", "mentalModel": "One counterexample breaks the rule."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$fe694b93-0d0a-52a1-b343-5d95c6015cdd$ml$::uuid, $ml$neuroscience$ml$, 8, 3, $ml${"id": "neuroscience-d8-c3", "title": "What a new mechanism is worth", "lessonTitle": "A $14 billion bet on a new target", "slot": 3, "type": "decide", "brief": {"headline": "You run business development at a drugmaker. A biotech offers a late-stage psychiatric drug with a new mechanism, at a big price. BMS paid about $14 billion for Karuna.", "kicker": "Decide what to pay for, and what to check first.", "fullText": "You run business development at a mid-size drugmaker. A biotech offers a psychiatric drug with a new mechanism, in late-stage trials, and asks for a big price.\n\nDay 8 gives you the reference. Bristol Myers Squibb paid about $14 billion for Karuna Therapeutics. Its drug, Cobenfy, was approved on September 26, 2024, as the first antipsychotic to target cholinergic rather than dopamine receptors, at a list price of $1,850 a month, about $22,500 a year, in line with other branded antipsychotics. A new mechanism can be worth billions, but the buyer pays before the final answer.", "sources": [{"url": "https://www.fiercepharma.com/pharma/bristol-myers-squibbs-karuna-buyout-pays-approval-novel-schizophrenia-med-cobenfy", "label": "Fierce Pharma, BMS's Karuna buyout pays off with FDA approval for Cobenfy, Sep 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which asset fits the logic behind the Karuna deal?", "left": {"name": "A new mechanism in Phase 3", "note": "First of its kind, if approved"}, "right": {"name": "One more dopamine drug", "note": "Joins a long-crowded class"}, "correctIndex": 0, "explanation": "Big drugmakers pay to own new ways of treating disease. BMS paid about $14 billion for one."}, "numbers": {"kind": "numberSense", "prompt": "At about $22,500 a year, how many thousand patient-years of sales make $1 billion?", "min": 0, "max": 100, "value": 44, "unit": "K", "explanation": "$1 billion divided by $22,500 is about 44,000 patient-years at list price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks you to explain, in one line, why BMS paid $14 billion for Karuna.", "prompt": "What do you say?", "options": ["It bought a cheaper copy of old drugs", "It bought Karuna for its buildings", "It bought a new way to treat schizophrenia"], "correctIndex": 2, "consequences": ["Cobenfy was new, priced like other branded antipsychotics.", "The value was the drug and its mechanism.", "Cobenfy was the first antipsychotic to target cholinergic receptors."], "explanation": "BMS paid for a new mechanism. That is the one-line answer."}, "proReasoning": "Explain big deals by what is new. Big drugmakers buy biotechs to own new ways of treating disease.", "commonMistake": "Explaining a deal by its size rather than by what was bought.", "mentalModel": "Deals buy novelty."}, "invest": {"call": {"kind": "theCall", "situation": "You're judging whether the biotech's asking price is fair.", "prompt": "What should anchor your valuation?", "options": ["Approval odds times the market if new", "Karuna's $14 billion, with no changes", "What the biotech has spent so far"], "correctIndex": 0, "consequences": ["Novelty sets the prize; trial odds set what you should pay.", "Karuna's drug had its own data and timing.", "Past spending says nothing about future value."], "explanation": "A reference deal is a starting point. Scale it by this drug's odds and market."}, "proReasoning": "Investors scale a reference deal by the odds and the market. A new mechanism raises the prize, not the certainty.", "commonMistake": "Copying a famous price without adjusting for risk.", "mentalModel": "Prize times odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the biotech's founder. A buyer offers less than Karuna got.", "prompt": "What strengthens your position most?", "options": ["Saying your drug is like the old ones", "Evidence your mechanism is truly new", "Pointing to how much BMS paid"], "correctIndex": 1, "consequences": ["Sameness lowers the price.", "New mechanisms drive the big deals, so prove novelty.", "Their price reflected their drug, not yours."], "explanation": "Buyers pay premiums for mechanisms they cannot get elsewhere. Prove yours is one."}, "proReasoning": "Founders sell what is new about their drug. Buyers pay premiums for mechanisms they cannot get elsewhere.", "commonMistake": "Arguing from another company's price instead of your own data.", "mentalModel": "Prove the novelty."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend can't see why a company would pay billions for a drug not yet approved.", "prompt": "What's the best explanation?", "options": ["Approval was already guaranteed", "The drug was already selling well", "A new mechanism could open a new market"], "correctIndex": 2, "consequences": ["No approval is guaranteed before the FDA decides.", "Before approval, it had no sales.", "BMS paid about $14 billion; Cobenfy was approved later."], "explanation": "Drugmakers buy future markets. The bet paid off for BMS when Cobenfy was approved."}, "proReasoning": "Big pharma buys future markets. A new mechanism can be worth billions even before approval, if the bet pays off.", "commonMistake": "Thinking deals only buy drugs already on sale.", "mentalModel": "Buy the future, accept the risk."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$cc46dbd9-e151-57ac-b228-6d2534a78596$ml$::uuid, $ml$neuroscience$ml$, 9, 1, $ml${"id": "neuroscience-d9-c1", "title": "The Adderall ceiling moves", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, the DEA raised the 2025 quota for d-amphetamine, Adderall's main active ingredient, by about 25%. It said the old quota met medical demand, as the shortage entered its third year.", "kicker": "Apply the ceiling: who decided how much of Adderall's ingredient was made?", "fullText": "On October 2, 2025, the DEA published a final order raising two 2025 aggregate production quotas. d-amphetamine went from 21.2 million grams to 26.45 million grams, and methylphenidate from 53.28 million to 58.28 million grams. Each followed a manufacturer's request in August 2025 citing a shortage of an active ingredient, and the DEA checked the FDA's shortage list.\n\nThe DEA said the old quotas were adequate for medical demand, and that the increases were mainly for product development, such as FDA approval of new manufacturing processes and products. Filter noted the d-amphetamine cap had not changed since 2021, and that at least five makers of amphetamine salts reported shortages.\n\nAs on day 9, the market did not set the supply. A regulator did.", "sources": [{"url": "https://public-inspection.federalregister.gov/2025-19335.pdf", "label": "Federal Register, DEA adjusts 2025 quotas for d-amphetamine and methylphenidate, Oct 2025"}, {"url": "https://filtermag.org/dea-adderall-production-quotas-adhd-medication-shortage/", "label": "Filter, DEA raises Adderall production quotas, Oct 2025"}, {"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the quota change in order.", "steps": ["A manufacturer reports an ingredient shortage", "It asks the DEA to raise the quota", "The DEA checks the FDA's shortage list", "The DEA publishes a higher quota", "Makers may produce more, up to the new ceiling"], "explanation": "Makers could not simply produce more. They had to ask, and the DEA decided."}, "numbers": {"kind": "numberSense", "prompt": "The d-amphetamine quota rose from 21.2 to 26.45 million grams. By about what percent?", "min": 0, "max": 60, "value": 25, "unit": "%", "explanation": "An increase of 5.25 million grams, about 25%, after four years without a change."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a generic drugmaker's supply team. Amphetamine salts are on the shortage list.", "prompt": "What decides how much can be made next year?", "options": ["How fast your plant can run", "The DEA's production quota", "How many orders pharmacies send"], "correctIndex": 1, "consequences": ["Plant speed matters only up to the quota.", "For Schedule II drugs, the DEA quota is the ceiling.", "Demand alone cannot raise a controlled ceiling."], "explanation": "For a Schedule II drug, supply planning starts with the DEA quota, not with orders."}, "proReasoning": "In controlled drugs, supply planning starts with the quota. Knowing how the DEA sets and adjusts it is part of the job.", "commonMistake": "Planning production from demand alone.", "mentalModel": "The quota is the ceiling."}, "invest": {"call": {"kind": "theCall", "situation": "A maker of ADHD stimulants says demand is surging. The DEA says medical demand fits within the quota.", "prompt": "How should you read the growth story?", "options": ["Rising demand guarantees higher sales", "Quotas apply only to brand-new drugs", "Growth is capped by what the DEA allows"], "correctIndex": 2, "consequences": ["A quota can hold supply below demand.", "Quotas cover each Schedule II substance every year.", "Sales cannot outrun the production ceiling."], "explanation": "For a controlled drug, the quota caps volume. Surging demand can mean shortages, not sales."}, "proReasoning": "Investors put the DEA's ceiling into any controlled drug thesis. A shortage can mean lost sales, not pricing power.", "commonMistake": "Assuming high demand turns into high volume.", "mentalModel": "Demand meets a ceiling."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks pharmacy stock of ADHD drugs. The shortage is in its third year.", "prompt": "Which signal should your tool watch most closely?", "options": ["DEA quota changes and shortage lists", "Social media posts about ADHD meds", "Prices of drugs that have no quota"], "correctIndex": 0, "consequences": ["Quota moves and shortage lists change what can be made and sold.", "Posts reflect demand, not the supply ceiling.", "Drugs without a quota face no such ceiling."], "explanation": "Supply of these drugs moves when the DEA moves. Track the ceiling."}, "proReasoning": "Founders track the variable that actually moves supply. For stimulants, that is the DEA quota and the shortage list.", "commonMistake": "Watching demand signals when the bottleneck is a regulator.", "mentalModel": "Watch the ceiling, not the crowd."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why drugmakers didn't just make more Adderall during the shortage.", "prompt": "What's the answer?", "options": ["It is banned outright in the US", "The DEA caps how much can be made", "No company wanted to make it"], "correctIndex": 1, "consequences": ["It is a controlled drug, not a banned one.", "Makers need DEA quota to produce more of a Schedule II drug.", "At least five makers of amphetamine salts reported shortages."], "explanation": "For Schedule II drugs, the DEA sets a yearly ceiling. Makers had to ask to make more."}, "proReasoning": "When a needed drug runs short, ask who sets the supply. For Schedule II drugs, it is the DEA.", "commonMistake": "Assuming companies simply chose not to make more.", "mentalModel": "Ask who sets the supply."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$d464cb0f-aca8-526a-81f4-42aeec493aea$ml$::uuid, $ml$neuroscience$ml$, 9, 2, $ml${"id": "neuroscience-d9-c2", "title": "Two regulators, two questions", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 2, "type": "connect", "brief": {"headline": "The FDA decides whether a drug may be sold. For Schedule II drugs, the DEA also decides how much can be made: in 2025 it raised the lisdexamfetamine quota by about 22%.", "kicker": "Connect day 3 and day 9: one gate on safety, one on supply.", "fullText": "On day 3 you met the regulator as a gatekeeper: the FDA decides what can be tested and sold, and it classes implanted brain-computer interfaces as significant risk devices. On day 9 you met a second regulator. Under the Controlled Substances Act, the DEA sets aggregate production quotas for each Schedule I and II substance.\n\nIn September 2025, with lisdexamfetamine products on the FDA's shortage list, the DEA raised the 2025 lisdexamfetamine quota from 32,736,000 grams to 39,907,536 grams. An approved drug can still be scarce if the second regulator caps how much of it can be made.", "sources": [{"url": "https://www.hhs.gov/guidance/sites/default/files/hhs-guidance-documents/FDA/Brain-Computer-Interface-Guidance.pdf", "label": "FDA guidance, Implanted brain-computer interface devices (2021)"}, {"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which regulator sets how much lisdexamfetamine can be produced each year?", "left": {"name": "The FDA", "note": "Approves drugs and keeps the shortage list"}, "right": {"name": "The DEA", "note": "Sets yearly quotas for Schedule II drugs"}, "correctIndex": 1, "explanation": "The FDA approved the drug and listed the shortage. The DEA set, and then raised, the ceiling on production."}, "numbers": {"kind": "numberSense", "prompt": "By law, the DEA must answer a shortage-related quota request within how many days?", "min": 0, "max": 90, "value": 30, "unit": "days", "explanation": "Within 30 days. Even the second regulator works on a clock when patients go without."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a company with an approved ADHD stimulant. They ask what limits its growth.", "prompt": "Which answer shows you know the field?", "options": ["Only what the FDA label allows", "Only the number of prescribers", "DEA quotas, on top of FDA approval"], "correctIndex": 2, "consequences": ["The label is one gate; the quota is another.", "Prescribers matter, but supply is capped by the DEA.", "Approval lets it be sold; the quota caps how much is made."], "explanation": "A controlled drug passes two regulators: one on safety, one on supply."}, "proReasoning": "Name both gates for a controlled drug: FDA approval and DEA quota. Most candidates only know one.", "commonMistake": "Thinking approval is the last regulatory hurdle.", "mentalModel": "Approval, then quota."}, "invest": {"call": {"kind": "theCall", "situation": "A controlled drug wins FDA approval. Management projects sales doubling next year.", "prompt": "What's the first check?", "options": ["Whether DEA quota allows that much", "Whether the FDA might reverse itself", "Whether anyone wants the drug"], "correctIndex": 0, "consequences": ["Without quota, the drug cannot be made in that volume.", "The approval stands; supply is the open question.", "Demand may be real and still be capped."], "explanation": "For a controlled drug, volume needs quota. Check the ceiling before the forecast."}, "proReasoning": "For controlled drugs, investors check the quota before the forecast. A second regulator can cap volume.", "commonMistake": "Forecasting a controlled drug like any other.", "mentalModel": "Check the quota before the forecast."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your telehealth startup wants to prescribe a Schedule II stimulant at scale.", "prompt": "What must your growth plan assume?", "options": ["The FDA sets the monthly supply", "Supply may be capped by DEA quotas", "Supply grows with your patient count"], "correctIndex": 1, "consequences": ["The DEA sets production quotas, not the FDA.", "The DEA, not the market, sets the ceiling.", "Supply of Schedule II drugs is capped each year."], "explanation": "More patients does not mean more pills. The DEA ceiling holds either way."}, "proReasoning": "Founders in controlled drugs plan around the supply ceiling. More patients does not mean more pills.", "commonMistake": "Assuming supply will follow demand.", "mentalModel": "Plan inside the ceiling."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an approved medicine can still be hard to find.", "prompt": "What's one big reason?", "options": ["Approvals expire every year", "Pharmacies refuse to stock it", "A second regulator caps production"], "correctIndex": 2, "consequences": ["Approvals do not expire yearly; quotas are set yearly.", "The supply ceiling, not pharmacies, is the main limit.", "For Schedule II drugs, the DEA sets yearly quotas."], "explanation": "One regulator approves the drug; another caps how much of it is made."}, "proReasoning": "Explain shortages of controlled drugs with two regulators: one approves, one caps supply.", "commonMistake": "Assuming approval means unlimited supply.", "mentalModel": "Approved is not unlimited."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9589fb1f-f7f6-5127-aac6-5891865d70d4$ml$::uuid, $ml$neuroscience$ml$, 9, 3, $ml${"id": "neuroscience-d9-c3", "title": "Growing into a ceiling", "lessonTitle": "Who decides how much ADHD drug is made", "slot": 3, "type": "decide", "brief": {"headline": "You run an ADHD telehealth startup with demand rising fast. Lisdexamfetamine was on the FDA's shortage list until the DEA raised its 2025 quota by about 22%.", "kicker": "Decide how to grow when a regulator caps the supply.", "fullText": "You run a telehealth startup that connects adults with ADHD to prescribers, and sign-ups are rising. Under the Controlled Substances Act, the DEA sets how much of each Schedule II substance may be produced each year, covering medical, scientific and industrial needs, exports and reserves.\n\nIn August 2025 a manufacturer asked for more lisdexamfetamine, citing an active ingredient shortage, while capsules and chewable tablets were on the FDA's shortage list. In September, the DEA raised the 2025 quota by about 22%, pointing to rising global demand, including approvals of Vyvanse in 29 other countries. The law gives the DEA 30 days to answer such requests.", "sources": [{"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The DEA sets yearly quotas for Schedule II drugs.", "Makers can produce as much as demand requires.", "The DEA must answer shortage requests within 30 days."], "fakeIndex": 1, "explanation": "For controlled drugs, makers cannot simply produce more. The quota is the ceiling."}, "numbers": {"kind": "numberSense", "prompt": "The quota rose from about 32.7 to 39.9 million grams. How many million grams were added?", "min": 0, "max": 20, "value": 7.2, "unit": "M", "explanation": "About 7.2 million grams, roughly 22% more, decided by the DEA."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're hiring a head of pharmacy partnerships for the startup.", "prompt": "Which experience matters most?", "options": ["Managing supply during drug shortages", "Running social media ad campaigns", "Building consumer fitness apps"], "correctIndex": 0, "consequences": ["Quotas and shortages decide whether patients can fill prescriptions.", "Ads drive sign-ups that supply may not support.", "Useful skills, wrong problem."], "explanation": "Your bottleneck is supply, so hire for it."}, "proReasoning": "In controlled drugs, operations skill around supply is rare and valuable. Hire for the constraint.", "commonMistake": "Hiring for growth when the bottleneck is supply.", "mentalModel": "Hire for the constraint."}, "invest": {"call": {"kind": "theCall", "situation": "The startup asks you to fund a big marketing push.", "prompt": "What's your main concern?", "options": ["The DEA will ban telehealth tomorrow", "Patients may not be able to fill scripts", "Too few adults have ADHD"], "correctIndex": 1, "consequences": ["Nothing in the facts suggests that.", "With quotas capping supply, more sign-ups can mean unfilled scripts.", "Demand is rising; supply is the issue."], "explanation": "Marketing grows demand. The quota limits what patients can actually get."}, "proReasoning": "Investors ask whether growth can be served. When a regulator caps supply, marketing can outrun what patients can get.", "commonMistake": "Funding demand when supply is the bottleneck.", "mentalModel": "Can the growth be served?"}, "build_startup": {"call": {"kind": "theCall", "situation": "Sign-ups keep rising while the shortage continues. Your team proposes a response.", "prompt": "What's the soundest move?", "options": ["Promise every patient a fast refill", "Stop serving patients until supply returns", "Pace growth and help patients find stock"], "correctIndex": 2, "consequences": ["A promise the quota can break hurts patients and trust.", "Patients already in care still need support.", "You grow at the rate supply allows and keep trust."], "explanation": "Grow at the pace the ceiling allows, and help patients through the gaps."}, "proReasoning": "Founders under a supply ceiling grow at the pace the ceiling allows and help patients through the gaps.", "commonMistake": "Making promises a regulator's quota can break.", "mentalModel": "Grow at the pace of supply."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the DEA, an enforcement agency, decides how much medicine is made.", "prompt": "What's the reason?", "options": ["The law tasks it with drug quotas", "The FDA asked it to run pharmacies", "It owns the factories that make them"], "correctIndex": 0, "consequences": ["The Controlled Substances Act has it set yearly production quotas.", "The FDA keeps the shortage list; the DEA sets quotas.", "Manufacturers make the drugs; the DEA sets the cap."], "explanation": "Under the Controlled Substances Act, the DEA sets quotas for each Schedule I and II substance."}, "proReasoning": "Explain the DEA's role through the law: for Schedule I and II substances, it sets how much may be made.", "commonMistake": "Assuming drug supply is set by companies alone.", "mentalModel": "The law puts the DEA in charge."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ca53949e-2ebc-50f2-b03d-75f4bfa10946$ml$::uuid, $ml$neuroscience$ml$, 10, 1, $ml${"id": "neuroscience-d10-c1", "title": "One in five teens", "lessonTitle": "How many people take antidepressants", "slot": 1, "type": "apply", "brief": {"headline": "A CDC report in April 2025 found 13.1% of Americans 12 and older had depression in 2021 to 2023, up from 8.2% a decade earlier. Among teens 12 to 19, it was 19.2%.", "kicker": "Apply the market lens: who has depression, and who gets care?", "fullText": "The NCHS data brief measured depression with a standard questionnaire covering the past two weeks, from August 2021 to August 2023. Prevalence was 13.1% overall, 16.0% in females and 10.1% in males. It was highest in adolescents, 19.2%, and reached 26.5% among girls 12 to 19. It fell with age, to 8.7% of adults 60 and over.\n\nOnly 39.3% of people with depression had received counseling or therapy from a mental health professional in the past year, and 87.9% reported at least some difficulty with work, home or social activities.\n\nThe day 10 lesson counted who takes antidepressants. This survey counts who has depression, and how many go without therapy.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db527.htm", "label": "CDC NCHS, Depression prevalence in adolescents and adults, Apr 2025"}, {"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "sortSignal", "prompt": "Was each group above or below the 13.1% overall rate?", "buckets": ["Above 13.1%", "Below 13.1%"], "items": [{"text": "Teens 12 to 19", "bucket": 0}, {"text": "Girls 12 to 19", "bucket": 0}, {"text": "Females of all ages", "bucket": 0}, {"text": "Males of all ages", "bucket": 1}, {"text": "Adults 60 and over", "bucket": 1}], "explanation": "Teens, girls and females overall ran above the average. Males and older adults ran below it."}, "numbers": {"kind": "numberSense", "prompt": "What share of people with depression had counseling or therapy in the past year?", "min": 0, "max": 100, "value": 39, "unit": "%", "explanation": "About 39%. More than 60% went without professional therapy in the past year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a youth mental health company. They ask what the latest data shows.", "prompt": "Which fact lands best?", "options": ["Depression mostly affects people over 60", "Rates have barely changed in a decade", "19.2% of teens 12 to 19 had depression"], "correctIndex": 2, "consequences": ["Adults 60 and over had the lowest rate, 8.7%.", "Overall it rose from 8.2% to 13.1%.", "It is the highest rate of any age group."], "explanation": "The teen rate is the number that matches a youth company's mission."}, "proReasoning": "Bring the one number that matches the company's mission. For a youth company, it is the 19.2% teen rate.", "commonMistake": "Quoting a general statistic that misses the company's users.", "mentalModel": "Match the number to the mission."}, "invest": {"call": {"kind": "theCall", "situation": "A therapy platform cites the report: only 39.3% of people with depression got therapy last year.", "prompt": "How do you read that number?", "options": ["A large group with unmet need", "Proof that therapy does not work", "A sign the market is saturated"], "correctIndex": 0, "consequences": ["Over 60% went without professional therapy in the past year.", "The figure measures access, not effectiveness.", "Most people with depression were not in therapy."], "explanation": "Low treatment rates point to unmet need. Whether that need pays is the next question."}, "proReasoning": "Investors separate unmet need from willingness to pay. A big untreated group is a start, not a business by itself.", "commonMistake": "Reading low treatment rates as low demand.", "mentalModel": "Unmet need is not yet revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing a first audience for a depression support tool.", "prompt": "Which fact best points to a group in need?", "options": ["Overall rates rose from 8.2% to 13.1%", "26.5% of girls 12 to 19 had depression", "Adults 60 and over had the lowest rate"], "correctIndex": 1, "consequences": ["True, but it does not pick an audience.", "It is the highest rate in the report.", "A lower rate means a smaller group to serve."], "explanation": "Teen girls had the highest rate in the report, 26.5%."}, "proReasoning": "Founders pick a first audience from the sharpest number. Teen girls stand out at 26.5%.", "commonMistake": "Starting with everyone because the overall rate is high.", "mentalModel": "Start where the rate is highest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether depression is really more common now.", "prompt": "What does the CDC data say?", "options": ["It has stayed about flat since 2013", "It fell, especially among young people", "It rose from 8.2% to 13.1% in a decade"], "correctIndex": 2, "consequences": ["It rose by more than half.", "Teens had the highest rate, 19.2%.", "The rise was similar for females and males."], "explanation": "From 2013 to 2014 to 2021 to 2023, prevalence rose from 8.2% to 13.1%."}, "proReasoning": "Answer with the trend and its starting point: 8.2% in 2013 to 2014, 13.1% in 2021 to 2023.", "commonMistake": "Answering from impressions instead of data.", "mentalModel": "Trend plus baseline."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$aa636141-9a70-5711-ac78-bb17f27ff75e$ml$::uuid, $ml$neuroscience$ml$, 10, 2, $ml${"id": "neuroscience-d10-c2", "title": "Price times patients", "lessonTitle": "How many people take antidepressants", "slot": 2, "type": "connect", "brief": {"headline": "Leqembi launched at $26,500 a year, but price is only half of sales. Antidepressants show the other half: 13.2% of US adults had used one in the past 30 days in 2015 to 2018.", "kicker": "Connect day 2 and day 10: drug sales are price times patients.", "fullText": "On day 2 you met drug sales as one of the three streams of brain money, and Leqembi's $26,500 yearly price. The lesson's point for investors: revenue depends on how many patients get a drug and who pays.\n\nOn day 10 you saw the patient side at scale. A CDC survey found 13.2% of US adults used an antidepressant in the past 30 days during 2015 to 2018, and use rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018. A high price for a few patients and a modest price for many can both build a large stream.", "sources": [{"url": "https://biopharma-reporter.com/Article/2023/01/10/Next-steps-for-lecanemab-Eisai-reveals-pricing-US-and-global-rollout-plans", "label": "BioPharma Reporter, Eisai reveals Leqembi pricing"}, {"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What two things set a drug's sales?", "options": ["The number of messengers it targets", "Price and the number of patients treated", "Price alone, whatever the volume"], "correctIndex": 1, "explanation": "Revenue is price times patients treated, shaped by who pays."}, "numbers": {"kind": "numberSense", "prompt": "Antidepressant use rose from 10.6% to 13.8% of US adults. By how many percentage points?", "min": 0, "max": 10, "value": 3.2, "unit": "points", "explanation": "3.2 points, a rise of about 30% in the share of adults using them."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're weighing jobs on a high-priced Alzheimer's drug and a common antidepressant.", "prompt": "How do their sales engines differ?", "options": ["Few patients at a high price, or many", "They earn in exactly the same way", "Only the costly drug earns revenue"], "correctIndex": 0, "consequences": ["Both multiply price by patients, from opposite ends.", "Their mix of price and volume is very different.", "Common drugs earn through volume."], "explanation": "Every drug earns price times patients. The mix shapes what the commercial team worries about."}, "proReasoning": "Know how your product earns: price, volume or both. It shapes what the commercial team worries about.", "commonMistake": "Judging a drug's business by its price tag.", "mentalModel": "Price times patients."}, "invest": {"call": {"kind": "theCall", "situation": "A company touts its drug's high price. You want to estimate sales.", "prompt": "What else must you know?", "options": ["How many years it took to develop", "How many patients get it, and who pays", "Only how its price compares to rivals"], "correctIndex": 1, "consequences": ["Development time does not set sales.", "Revenue is price times patients treated.", "Price alone tells you nothing about volume."], "explanation": "Price is half the story. Patients treated and who pays decide the revenue."}, "proReasoning": "Investors never stop at price. Patients treated and who pays decide the revenue.", "commonMistake": "Letting a headline price stand in for sales.", "mentalModel": "Price is half the story."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a service for people on antidepressants. A cofounder worries the market is small.", "prompt": "Which fact answers that?", "options": ["Leqembi costs $26,500 a year", "There are at least 100 messengers", "13.2% of US adults used one in a month"], "correctIndex": 2, "consequences": ["True, but it is about a different drug.", "True, but not about market size.", "That is more than one in eight adults."], "explanation": "More than one in eight adults is a very large base of users."}, "proReasoning": "Founders size a market by users. More than one in eight adults is a very large base.", "commonMistake": "Sizing a market by price instead of people.", "mentalModel": "Count the users."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a cheap, common drug can earn as much as an expensive one.", "prompt": "What's the answer?", "options": ["Sales are price times patients", "Cheap drugs never earn much", "The NIH sets drug prices"], "correctIndex": 0, "consequences": ["Many patients at a low price can match few at a high one.", "Volume can make up for price.", "The NIH funds research; it does not set prices."], "explanation": "Revenue is price times patients. Either side can be big."}, "proReasoning": "Explain drug revenue with one formula: price times patients. Either side can be big.", "commonMistake": "Assuming the most expensive drugs earn the most.", "mentalModel": "Price times patients."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$7d371a44-8231-5a28-9468-f62973cc1371$ml$::uuid, $ml$neuroscience$ml$, 10, 3, $ml${"id": "neuroscience-d10-c3", "title": "Planning for steady growth", "lessonTitle": "How many people take antidepressants", "slot": 3, "type": "decide", "brief": {"headline": "You plan production at a generic antidepressant maker. US adult use rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018, and was highest among older adults.", "kicker": "Decide how to plan supply for a growing, uneven market.", "fullText": "You run demand planning at a maker of generic antidepressants. The CDC data you rely on: 13.2% of US adults used an antidepressant in the past 30 days in 2015 to 2018. Use was 17.7% among women and 8.4% among men, and rose with age, from 7.9% of adults 18 to 39 to 19.0% of those 60 and over, reaching 24.3% of women 60 and over.\n\nUse rose from 10.6% in 2009 to 2010 to 13.8% in 2017 to 2018. Your job is to turn that trend and that mix into a supply plan.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}]}, "evidence": {"kind": "faceOff", "prompt": "Which group used antidepressants at the higher rate?", "left": {"name": "Adults 18 to 39", "note": "Younger adults"}, "right": {"name": "Adults 60 and over", "note": "Older adults"}, "correctIndex": 1, "explanation": "19.0% of adults 60 and over, against 7.9% of adults 18 to 39. Use rose with age."}, "numbers": {"kind": "numberSense", "prompt": "Use among women 60 and over was 24.3%. About how many times the 7.9% rate for adults 18 to 39 is that?", "min": 0, "max": 8, "value": 3.1, "unit": "times", "explanation": "24.3 divided by 7.9 is about 3. Demand is very uneven across groups."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for one sentence on why antidepressant demand should keep growing.", "prompt": "Which is best supported?", "options": ["Use is falling among older women", "Use rose about 30% in eight years", "Every adult will soon take one"], "correctIndex": 1, "consequences": ["Women 60 and over had the highest rate, 24.3%.", "10.6% to 13.8% is a rise of about 30%.", "Use was 13.2%, far from everyone."], "explanation": "The trend, with its size, is the strongest support for a forecast."}, "proReasoning": "Support a forecast with the trend and its size. 10.6% to 13.8% is a steady, measurable rise.", "commonMistake": "Forecasting from impressions instead of the trend.", "mentalModel": "Forecast from the trend."}, "invest": {"call": {"kind": "theCall", "situation": "You're looking at a generic antidepressant maker's stock.", "prompt": "What does the CDC trend tell you about its volumes?", "options": ["Demand has collapsed since 2010", "Demand swings at random each year", "Demand has grown steadily"], "correctIndex": 2, "consequences": ["It rose, not fell.", "The surveys show a steady upward trend.", "Use rose from 10.6% to 13.8% over about eight years."], "explanation": "A steady rise in use supports volume, even for low-priced generics."}, "proReasoning": "Investors look for durable demand. A steady rise in use supports volume, even if prices are low.", "commonMistake": "Ignoring volume trends in low-price products.", "mentalModel": "Steady demand, steady volume."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup supplies pharmacies. You must choose where to add antidepressant stock first.", "prompt": "Which areas likely need more stock?", "options": ["Areas with many older adults", "Areas with mostly young men", "Areas with no pharmacies at all"], "correctIndex": 0, "consequences": ["Use rose with age, to 19.0% of adults 60 and over.", "Men and younger adults had lower use.", "No pharmacies, no customers for you."], "explanation": "Group rates turn into geography. Older populations use more."}, "proReasoning": "Founders turn group rates into geography. Where older adults and women cluster, demand runs higher.", "commonMistake": "Spreading stock evenly when use is uneven.", "mentalModel": "Stock where use is highest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that older adults use antidepressants more than younger ones.", "prompt": "What does the data show?", "options": ["Use is the same at every age", "19.0% at 60-plus, 7.9% at 18 to 39", "Younger adults use them twice as much"], "correctIndex": 1, "consequences": ["It ranged from 7.9% to 19.0% by age.", "Use rose with age in the CDC survey.", "The reverse: older adults used them more."], "explanation": "In the CDC survey, use rose steadily with age."}, "proReasoning": "Check surprising claims against group rates. Here, use clearly rose with age.", "commonMistake": "Assuming the group in the news is the biggest user.", "mentalModel": "Check the group rates."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a907296c-e96e-5d58-9195-afebc137e811$ml$::uuid, $ml$neuroscience$ml$, 11, 1, $ml${"id": "neuroscience-d11-c1", "title": "Clozapine loses its REMS", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 1, "type": "apply", "brief": {"headline": "On June 13, 2025, the FDA ended the safety program that required blood results before clozapine could be dispensed. Blood monitoring is still recommended; the program is gone.", "kicker": "Apply the lesson: when a safety rule goes, access changes.", "fullText": "Clozapine, an antipsychotic first approved in 1989, can cause severe neutropenia, a drop in a type of white blood cell that can lead to serious infections. Under its REMS, prescribers, pharmacies and patients had to enroll, and absolute neutrophil count results had to be reported before the drug could be dispensed.\n\nIn November 2024, FDA advisory committees agreed blood monitoring should continue but REMS documentation was no longer needed. In February 2025 the FDA said it no longer expected participation, and on June 13, 2025, it eliminated the REMS. The FDA said the program could impede access and expected removal to improve it. Prescribers should still monitor blood counts as the label says, and the label keeps a boxed warning.", "sources": [{"url": "https://www.fda.gov/drugs/drug-safety-and-availability/fda-removes-risk-evaluation-and-mitigation-strategy-rems-program-antipsychotic-drug-clozapine", "label": "FDA, FDA removes REMS program for the antipsychotic drug clozapine, 2025"}, {"url": "https://www.psychiatrictimes.com/view/fda-officially-eliminates-clozapine-rems", "label": "Psychiatric Times, FDA officially eliminates clozapine REMS, Jun 2025"}, {"url": "https://ncpa.org/newsroom/qam/2025/03/31/clozapine-rems-has-ended", "label": "NCPA, Clozapine REMS has ended, Mar 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did each item end with the REMS, or stay in place?", "buckets": ["Ended with the REMS", "Still in place"], "items": [{"text": "Enrolling prescribers and pharmacies", "bucket": 0}, {"text": "Reporting blood results before dispensing", "bucket": 0}, {"text": "Blood count monitoring by prescribers", "bucket": 1}, {"text": "A boxed warning on the label", "bucket": 1}, {"text": "The risk of severe neutropenia", "bucket": 1}], "explanation": "The program and its paperwork ended. The risk, the warning and the recommended monitoring stayed."}, "numbers": {"kind": "numberSense", "prompt": "Clozapine was first approved in 1989. About how many years later did the FDA end its REMS?", "min": 0, "max": 60, "value": 36, "unit": "years", "explanation": "From 1989 to 2025 is 36 years. Safety rules can change long after approval."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a hospital pharmacist in mid-2025. Your team asks what changes for clozapine.", "prompt": "What's the accurate summary?", "options": ["No REMS paperwork, but monitoring continues", "No more blood tests are needed at all", "Clozapine has been pulled from the market"], "correctIndex": 0, "consequences": ["The FDA still recommends blood count monitoring.", "Monitoring is still recommended in the label.", "It remains available, now without the REMS."], "explanation": "The REMS ended; the clinical monitoring did not."}, "proReasoning": "When a REMS ends, separate the paperwork from the medicine. Clinical monitoring can stay even when the program goes.", "commonMistake": "Assuming the risk ended with the program.", "mentalModel": "Program gone, risk remains."}, "invest": {"call": {"kind": "theCall", "situation": "Clozapine's REMS ends in 2025. You follow companies that make or support it.", "prompt": "What's the most likely effect?", "options": ["Higher paperwork costs for pharmacies", "Easier access for patients and clinics", "A ban on new prescriptions"], "correctIndex": 1, "consequences": ["Pharmacies no longer need blood results before dispensing.", "The FDA expected removal to improve access.", "Nothing was banned; a requirement was lifted."], "explanation": "The FDA said the REMS could impede access. Removing it should widen use."}, "proReasoning": "Investors read safety rules as a cap on reach. Removing one can widen use, as the FDA expected here.", "commonMistake": "Assuming rule changes only matter to regulators.", "mentalModel": "Rules cap reach."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sold software that helped clinics handle clozapine REMS reporting.", "prompt": "What's your smartest pivot?", "options": ["Keep selling REMS reporting as before", "Lobby to bring the REMS back", "Help clinics run blood monitoring well"], "correctIndex": 2, "consequences": ["There is no REMS left to report to.", "The FDA found the REMS no longer necessary.", "Monitoring is still recommended, so the need moves there."], "explanation": "The paperwork went away; the monitoring work did not. Follow the work."}, "proReasoning": "When a rule your product served disappears, founders follow the work that remains. Here, the monitoring stayed.", "commonMistake": "Betting on a requirement the regulator just removed.", "mentalModel": "Follow the work that remains."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that the FDA dropped clozapine's safety program and worries the drug is less safe.", "prompt": "What's a fair explanation?", "options": ["The risk is still labeled and monitored", "The drug was found to be risk-free", "The FDA stopped regulating the drug"], "correctIndex": 0, "consequences": ["It keeps a boxed warning, and blood monitoring is still recommended.", "Severe neutropenia is still a known risk.", "The FDA still oversees its label and warnings."], "explanation": "A REMS is one safety tool. Warnings and monitoring remain without it."}, "proReasoning": "Explain that a REMS is one tool among several. Removing it can improve access while warnings and monitoring remain.", "commonMistake": "Equating less paperwork with less safety.", "mentalModel": "Paperwork is not the only safety."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$dc34880f-5c9a-5910-8a83-036ba49b781f$ml$::uuid, $ml$neuroscience$ml$, 11, 2, $ml${"id": "neuroscience-d11-c2", "title": "A ceiling and a room", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 2, "type": "connect", "brief": {"headline": "The DEA caps how much of a Schedule II drug can be made. Spravato's REMS decides where it can be given: certified sites, with at least 2 hours of monitoring.", "kicker": "Connect day 9 and day 11: two rules, two different limits.", "fullText": "On day 9 you saw the DEA set aggregate production quotas for each Schedule I and II substance, a ceiling on supply. On day 11 you saw a different kind of limit. Spravato, J&J's esketamine nasal spray, is available only through a REMS: patients take it at certified healthcare settings under supervision and are monitored for at least 2 hours, because of risks including sedation, dissociation, slowed breathing and misuse.\n\nOne rule limits how much can be made. The other limits where and how a drug is used. Yet Spravato's sales grew 40% in the second quarter of 2026, to $584 million.", "sources": [{"url": "https://www.govinfo.gov/content/pkg/FR-2025-09-19/html/2025-18110.htm", "label": "Federal Register, DEA adjusts 2025 aggregate production quotas for lisdexamfetamine and d-amphetamine, Sep 2025"}, {"url": "https://www.jnjmedicalconnect.com/products/spravato/medical-content/how-will-i-take-spravato", "label": "Johnson & Johnson Medical Connect, How will I take Spravato"}, {"url": "https://www.biospace.com/business/j-j-sees-spravato-sales-surge-as-psychedelic-competitors-loom", "label": "BioSpace, J&J sees Spravato sales surge as psychedelic competitors loom, Jul 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "Which kind of rule decides where Spravato can be given?", "left": {"name": "A DEA production quota", "note": "Caps how much of a drug is made"}, "right": {"name": "An FDA REMS", "note": "Sets where and how a drug is used"}, "correctIndex": 1, "explanation": "Spravato's REMS requires certified sites and at least 2 hours of monitoring. A quota limits supply, not setting."}, "numbers": {"kind": "numberSense", "prompt": "Spravato sold $584 million in the second quarter of 2026, up 40%. About how much a year earlier, in millions?", "min": 0, "max": 1000, "value": 417, "unit": "M", "explanation": "$584 million divided by 1.4 is about $417 million. Strong growth, inside tight rules."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at a psychiatric drug company, you're asked how rules shape its products.", "prompt": "Which answer shows range?", "options": ["Rules apply only to illegal street drugs", "Quotas cap supply; a REMS limits setting", "Only the FDA approval really matters"], "correctIndex": 1, "consequences": ["Approved drugs face quotas and REMS too.", "Two different rules, two different limits on a drug.", "Approval is only the first of several rules."], "explanation": "Quotas, REMS and approval each limit a drug in their own way."}, "proReasoning": "Show you know the different rule types: production quotas, REMS and approval. Each limits a drug in its own way.", "commonMistake": "Treating all drug rules as one.", "mentalModel": "Different rules, different limits."}, "invest": {"call": {"kind": "theCall", "situation": "Spravato's sales grew 40% while it stayed under a REMS.", "prompt": "What does that suggest?", "options": ["REMS programs boost demand", "The REMS was dropped in 2026", "Rules can cap reach, not growth"], "correctIndex": 2, "consequences": ["The REMS limits access; growth came despite it.", "Spravato was still under its REMS.", "Supervised dosing limits where it is given, yet sales grew."], "explanation": "Rules shape a drug's reach. Strong demand can still drive growth inside them."}, "proReasoning": "Investors weigh how a rule shapes reach. Spravato shows a drug can grow inside tight rules, if demand is strong.", "commonMistake": "Assuming a REMS makes a drug commercially weak.", "mentalModel": "Rules shape, not stop."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're planning a clinic network for a supervised brain drug.", "prompt": "Which rule shapes your clinic design most?", "options": ["The REMS rules on site and monitoring", "The DEA production quota for it", "The NIH grant rules for research"], "correctIndex": 0, "consequences": ["Certified sites and 2-hour monitoring set your space and staff.", "The quota limits supply, not your rooms.", "Grants fund research, not clinics."], "explanation": "The REMS decides the room, the staff and the time. Design for it first."}, "proReasoning": "Founders building around a supervised drug design for the REMS first. Monitoring time sets how many patients a site can serve.", "commonMistake": "Designing a clinic without the REMS in mind.", "mentalModel": "Design for the REMS."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some brain drugs are hard to get, for different reasons.", "prompt": "What's the best explanation?", "options": ["Doctors simply prefer the older drugs", "Some are capped in supply, some in setting", "They are all banned outright in the US"], "correctIndex": 1, "consequences": ["The limits come from rules, not preference.", "The DEA caps supply; a REMS limits where a drug is given.", "They are approved, with limits."], "explanation": "A supply ceiling and a supervised setting create different bottlenecks."}, "proReasoning": "Explain access with the type of rule: a supply ceiling or a supervised setting. Each creates a different bottleneck.", "commonMistake": "Lumping all access problems together.", "mentalModel": "Name the rule, name the bottleneck."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$4df6a0b2-93a7-5a9e-8e1d-5f46e87aae9d$ml$::uuid, $ml$neuroscience$ml$, 11, 3, $ml${"id": "neuroscience-d11-c3", "title": "How many chairs?", "lessonTitle": "Why some brain drugs need a supervised room", "slot": 3, "type": "decide", "brief": {"headline": "You run a psychiatry practice weighing whether to offer Spravato. Each dose needs a certified site and at least 2 hours of monitoring, and sales grew 40% in early 2026.", "kicker": "Decide what supervised dosing means for your clinic.", "fullText": "You run an outpatient psychiatry practice. Spravato, J&J's esketamine nasal spray, became in January 2025 the first monotherapy for treatment-resistant depression. It is available only through a REMS: patients take it at certified healthcare settings under a provider's supervision and must be monitored for at least 2 hours, because of risks of sedation, dissociation, slowed breathing, and abuse and misuse.\n\nDemand is growing: second quarter 2026 sales were $584 million, up 40%. Your decision is whether you can offer it, and how the 2-hour rule shapes your rooms and staff.", "sources": [{"url": "https://www.jnjmedicalconnect.com/products/spravato/medical-content/how-will-i-take-spravato", "label": "Johnson & Johnson Medical Connect, How will I take Spravato"}, {"url": "https://www.biospace.com/business/j-j-sees-spravato-sales-surge-as-psychedelic-competitors-loom", "label": "BioSpace, J&J sees Spravato sales surge as psychedelic competitors loom, Jul 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a Spravato visit in order.", "steps": ["The site is certified under the REMS", "The patient arrives for a scheduled dose", "The patient takes the spray under supervision", "Staff monitor the patient for at least 2 hours", "The patient leaves once monitoring ends"], "explanation": "Certification comes first, and the monitoring window is the longest part of every visit."}, "numbers": {"kind": "numberSense", "prompt": "If each monitoring chair holds one patient for at least 2 hours, how many doses can it host in an 8-hour day, at most?", "min": 0, "max": 12, "value": 4, "unit": "doses", "explanation": "Eight hours divided by two is four doses per chair at most. Chairs, not demand, set the ceiling."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The practice hires you as operations lead to launch Spravato.", "prompt": "Which staffing fact matters most?", "options": ["Doses can be mailed to patients at home", "No staff are needed once the dose is taken", "Each patient needs 2 hours of monitoring"], "correctIndex": 2, "consequences": ["It is taken under supervision at certified sites.", "Patients must be monitored for at least 2 hours.", "Monitoring time sets how many staff hours each dose takes."], "explanation": "The monitoring window turns into staff hours for every single dose."}, "proReasoning": "Operations leads turn safety rules into staff hours. A 2-hour monitoring window is a staffing plan.", "commonMistake": "Planning for the dose and forgetting the monitoring.", "mentalModel": "Rules become staff hours."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing a chain of clinics built around Spravato.", "prompt": "What limits each clinic's revenue most?", "options": ["Chairs and staff for 2-hour monitoring", "The price of a nasal spray bottle", "How many patients see its ads"], "correctIndex": 0, "consequences": ["Each chair handles only a few doses a day.", "Price matters, but capacity sets volume.", "Demand is growing; capacity is the cap."], "explanation": "With supervised dosing, chairs and staff hours set how many doses a clinic can give."}, "proReasoning": "Investors find the capacity limit in a service business. With supervised dosing, chairs and staff hours set the ceiling.", "commonMistake": "Valuing clinics on demand without checking capacity.", "mentalModel": "Capacity caps revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to help clinics offer Spravato.", "prompt": "Which product idea fits the REMS?", "options": ["An app that replaces staff monitoring", "Scheduling that fills monitoring chairs", "A home delivery service for the spray"], "correctIndex": 1, "consequences": ["The REMS requires a provider's supervision.", "Filling every 2-hour slot raises what each clinic can serve.", "It must be taken at certified sites."], "explanation": "Work inside the rule: help clinics use every monitoring slot they have."}, "proReasoning": "Founders build within the rule, not against it. Better scheduling helps clinics serve more patients under the same REMS.", "commonMistake": "Building a product the safety rules forbid.", "mentalModel": "Build inside the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their cousin spends half a day at a clinic for a nasal spray.", "prompt": "What's the reason?", "options": ["The spray takes hours to fully inhale", "Clinics charge patients by the hour", "Patients must be monitored for 2 hours"], "correctIndex": 2, "consequences": ["The dose is quick; the monitoring is long.", "The time comes from safety rules.", "The REMS requires monitoring for sedation and dissociation."], "explanation": "Risks like sedation and dissociation are why patients stay at least 2 hours."}, "proReasoning": "Explain supervised dosing by its risks: sedation, dissociation and slowed breathing are why patients stay.", "commonMistake": "Blaming the clinic for a time the rules require.", "mentalModel": "The rule sets the visit."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a6f04678-22b3-577f-9739-87fc3224600e$ml$::uuid, $ml$neuroscience$ml$, 12, 1, $ml${"id": "neuroscience-d12-c1", "title": "A retracted paper, a surviving theory", "lessonTitle": "When the serotonin story was challenged", "slot": 1, "type": "apply", "brief": {"headline": "In 2024, Nature retracted a landmark 2006 Alzheimer's paper on an amyloid protein, Aβ*56, after signs of image manipulation. Experts said one bad paper does not sink the whole amyloid theory.", "kicker": "Apply the lesson: separate a theory, a paper and a treatment.", "fullText": "The 2006 Nature paper, led by Sylvain Lesné with Karen Ashe among its co-authors, reported that a form of amyloid beta called Aβ*56 caused memory loss in rats. In 2022, Science reported concerns first raised by Vanderbilt neuroscientist Matthew Schrag, finding more than 20 suspect papers by Lesné and over 70 possible instances of image tampering. NBC News noted that more than $1 billion in NIH money had gone to amyloid-related Alzheimer's research.\n\nThe retraction note said figures showed signs of excessive manipulation, including splicing, duplication and use of an eraser tool. Lesné disagreed with the retraction. Ashe had said a retraction does not call the amyloid-beta hypothesis into question, and experts largely argued against discarding the whole theory.\n\nDrugs are judged separately: Leqembi won traditional approval in 2023 on a trial in which it slowed decline by 27%.", "sources": [{"url": "https://experts.umn.edu/en/publications/retraction-note-a-specific-amyloid-%CE%B2-protein-assembly-in-the-brai/", "label": "Nature retraction note via University of Minnesota, Jul 2024"}, {"url": "https://www.nbcnews.com/science/science-news/alzheimers-theory-undermined-accusations-fabricated-research-rcna39843", "label": "NBC News, Alzheimer's theory undermined by accusations of fabricated research, Jul 2022"}, {"url": "https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease", "label": "Eisai and Biogen via BioSpace, Leqembi traditional approval"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the retraction undermine most directly?", "options": ["The existence of amyloid plaques", "The Aβ*56 findings in that paper", "Every amyloid drug trial result"], "correctIndex": 1, "explanation": "The retraction concerned figures in one paper about Aβ*56. Drug trials stand or fall on their own data."}, "numbers": {"kind": "numberSense", "prompt": "Science's investigation found over how many possible instances of image tampering?", "min": 0, "max": 200, "value": 70, "unit": "instances", "explanation": "Over 70, across more than 20 suspect papers. One lab, many questions; the wider theory still had support."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an Alzheimer's biotech in 2025. They ask what the Lesné retraction means.", "prompt": "Which answer is most careful?", "options": ["It changes nothing at all for the field", "One strand is gone; trials judge the drugs", "The amyloid theory is now fully disproven"], "correctIndex": 1, "consequences": ["It removed a landmark paper and spurred new scrutiny.", "Experts kept the broad theory while rechecking Aβ*56.", "Experts largely argued against discarding the whole theory."], "explanation": "A retraction removes one finding. The broad theory and the drug trials are separate questions."}, "proReasoning": "Separate a paper, a theory and a treatment. A retraction can remove one finding without settling the others.", "commonMistake": "Turning one retraction into a verdict on a whole field.", "mentalModel": "Paper, theory, treatment."}, "invest": {"call": {"kind": "theCall", "situation": "After the retraction, a friend wants to sell every stock tied to amyloid drugs.", "prompt": "What's the better question?", "options": ["Which paper had the most citations?", "Whether rats can get Alzheimer's", "What do the drug trials themselves show?"], "correctIndex": 2, "consequences": ["Citations do not measure whether a drug works.", "The drug trials were in people, which is what counts.", "Leqembi was approved on a trial that slowed decline by 27%."], "explanation": "A drug is judged by its trials, not by one lab paper about a protein form."}, "proReasoning": "Investors back evidence of benefit, not neat stories. A drug's trial data matters more than any single theory paper.", "commonMistake": "Selling on a theory headline without checking the trial data.", "mentalModel": "Back trial data, not stories."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's Alzheimer's drug builds on research about specific amyloid forms.", "prompt": "What should you do after the Lesné news?", "options": ["Retest the findings you rely on", "Hide the link from investors", "Drop all amyloid research at once"], "correctIndex": 0, "consequences": ["Knowing your evidence base protects the program.", "Investors will find it, and trust will suffer.", "The broad theory still has support."], "explanation": "Audit the papers your program stands on, and replicate the ones that matter."}, "proReasoning": "Founders audit the papers their program stands on. Replicating key findings early beats discovering a problem late.", "commonMistake": "Building on a single famous paper without checking it.", "mentalModel": "Audit your foundations."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that a famous Alzheimer's paper was retracted for doctored images and asks if the drugs are bogus too.", "prompt": "What's a fair answer?", "options": ["The paper itself was about a drug", "Drugs are judged by their own trials", "Yes, all of them must be useless"], "correctIndex": 1, "consequences": ["It was about a protein form, Aβ*56.", "Leqembi slowed decline by 27% in its trial.", "Approved drugs were tested in their own trials."], "explanation": "A lab paper and a drug trial are different kinds of evidence. Each stands on its own."}, "proReasoning": "Explain the chain: lab theory, then drug, then trial. A drug stands on its trial, not on one lab paper.", "commonMistake": "Assuming a broken paper breaks every treatment in its field.", "mentalModel": "Treatments stand on trials."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$91501c3d-cc06-5867-a056-ed1153bdeef7$ml$::uuid, $ml$neuroscience$ml$, 12, 2, $ml${"id": "neuroscience-d12-c2", "title": "Millions of users, a broken story", "lessonTitle": "When the serotonin story was challenged", "slot": 2, "type": "connect", "brief": {"headline": "13.2% of US adults used an antidepressant in 2015 to 2018. In 2022, a review found no convincing evidence that low serotonin causes depression, a story 85% to 90% of the public believed.", "kicker": "Connect day 10 and day 12: a big market and a shaky story.", "fullText": "On day 10 you saw how common antidepressants are: 13.2% of US adults had used one in the past 30 days in 2015 to 2018, and use was rising. On day 12 you saw the explanation many of them heard come under fire. Joanna Moncrieff's 2022 umbrella review found no support for the idea that depression is caused by low serotonin, and the authors said 85% to 90% of the public believed it.\n\nThe review did not assess whether antidepressants work, and critics noted drugs can help without fixing a shortage. A huge market can rest on a treatment that helps and a story that does not hold.", "sources": [{"url": "https://www.cdc.gov/nchs/products/databriefs/db377.htm", "label": "CDC NCHS, Antidepressant use among adults: United States, 2015-2018"}, {"url": "https://www.sciencedaily.com/releases/2022/07/220720080145.htm", "label": "ScienceDaily via UCL, No evidence that depression is caused by low serotonin, Jul 2022"}, {"url": "https://www.newswise.com/articles/don-t-throw-away-your-antidepressants-just-yet", "label": "Newswise, Don't throw away your antidepressants just yet, 2022"}]}, "evidence": {"kind": "faceOff", "prompt": "Which question did the 2022 review actually test?", "left": {"name": "The low-serotonin cause", "note": "Is depression caused by low serotonin?"}, "right": {"name": "Antidepressant benefit", "note": "Do the drugs help patients?"}, "correctIndex": 0, "explanation": "The review tested the cause story. It did not assess whether antidepressants work."}, "numbers": {"kind": "numberSense", "prompt": "The authors said at least what share of the public believed the low-serotonin story?", "min": 0, "max": 100, "value": 85, "unit": "%", "explanation": "85% to 90%. A story can be almost universal and still lack support."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in medical communications for an antidepressant. A draft says it fixes a chemical imbalance.", "prompt": "What's the right edit?", "options": ["Keep it, since most people believe it", "Say the drug does not work", "Describe benefits shown in trials instead"], "correctIndex": 2, "consequences": ["Belief is not evidence, even at 85% to 90%.", "The review did not assess whether the drugs work.", "The review found no consistent evidence for low serotonin as the cause."], "explanation": "Explain a drug by evidence of benefit. A disputed cause story does not belong in the copy."}, "proReasoning": "Communicators explain treatments by evidence of benefit, not by a disputed cause. It keeps messages accurate as theories change.", "commonMistake": "Repeating a popular explanation the evidence does not support.", "mentalModel": "Explain the benefit, not the myth."}, "invest": {"call": {"kind": "theCall", "situation": "A company's pitch for a new antidepressant leans on fixing low serotonin.", "prompt": "How should that affect your view?", "options": ["Look for benefit, not the story", "Invest, since the public believes it", "Reject every antidepressant company"], "correctIndex": 0, "consequences": ["Drugs can help even if the theory behind them is wrong.", "Belief in a story does not prove a drug works.", "The review did not show antidepressants fail."], "explanation": "Theories shift; benefit in trials is what counts."}, "proReasoning": "Investors back evidence of benefit, not a neat mechanism story. Theories shift; trial results are what count.", "commonMistake": "Valuing a drug on a disputed theory.", "mentalModel": "Benefit beats story."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mental health app explains treatment to millions of users.", "prompt": "How should you explain antidepressants now?", "options": ["They have been proven useless", "They can help; the cause is unclear", "They work by fixing low serotonin"], "correctIndex": 1, "consequences": ["The review did not assess whether they work.", "Accurate, and in line with both the review and its critics.", "The 2022 review found no consistent support for that."], "explanation": "Honest uncertainty matches the evidence and keeps users' trust."}, "proReasoning": "Founders explaining health topics keep pace with the evidence. Honest uncertainty builds more trust than a tidy myth.", "commonMistake": "Using a simple story the science has moved past.", "mentalModel": "Honest uncertainty."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend on an antidepressant reads about the 2022 review and feels misled.", "prompt": "What's a fair way to put it?", "options": ["The drug was proven not to work at all", "The review was about painkillers", "The story was challenged, not the drug"], "correctIndex": 2, "consequences": ["It did not assess drug benefit.", "Painkillers were the critics' example of help without a shortage.", "The review did not test whether antidepressants work."], "explanation": "The review questioned why the drugs were said to work, not whether they help. Any change to treatment is a talk with their doctor."}, "proReasoning": "Separate why a drug was said to work from whether it helps. A broken story is not a broken treatment.", "commonMistake": "Concluding a drug fails because its popular explanation did.", "mentalModel": "Story and benefit are separate."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$fa86686d-88a2-5247-8d37-1c593ce4cfa0$ml$::uuid, $ml$neuroscience$ml$, 12, 3, $ml${"id": "neuroscience-d12-c3", "title": "Rewriting the explainer", "lessonTitle": "When the serotonin story was challenged", "slot": 3, "type": "decide", "brief": {"headline": "You run a health site whose antidepressant page says depression comes from low serotonin. A 2022 review found no convincing evidence for that, but did not test whether the drugs work.", "kicker": "Decide how to fix the page without misleading readers.", "fullText": "You run a popular health information site. Its page on antidepressants still says depression is caused by a chemical imbalance, low serotonin.\n\nIn July 2022, Moncrieff and colleagues published an umbrella review finding no support for that idea: blood and brain-fluid measures showed no difference, and lowering serotonin in healthy volunteers did not cause depression. The review did not assess whether antidepressants work. Critics such as UCL psychiatrist Michael Bloomfield noted the drugs can help even if low serotonin is not the cause, as painkillers help headaches. Many of your readers may be taking these drugs.", "sources": [{"url": "https://www.sciencedaily.com/releases/2022/07/220720080145.htm", "label": "ScienceDaily via UCL, No evidence that depression is caused by low serotonin, Jul 2022"}, {"url": "https://www.newswise.com/articles/don-t-throw-away-your-antidepressants-just-yet", "label": "Newswise, Don't throw away your antidepressants just yet, 2022"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did the 2022 review find this?", "buckets": ["The review found it", "It did not"], "items": [{"text": "No consistent link between low serotonin and depression", "bucket": 0}, {"text": "Lowering serotonin did not cause depression in volunteers", "bucket": 0}, {"text": "No difference in blood and brain-fluid measures", "bucket": 0}, {"text": "Antidepressants do not work", "bucket": 1}, {"text": "People on antidepressants should stop them", "bucket": 1}], "explanation": "The review tested the cause story. It made no finding on whether the drugs work, and gave no advice to stop them."}, "numbers": {"kind": "numberSense", "prompt": "If 85% of your 1,000 most loyal readers believe the old story, how many does the new page need to reach?", "min": 0, "max": 1000, "value": 850, "unit": "readers", "explanation": "85% of 1,000 is 850 readers who may hold the old story. That is the audience for the rewrite."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the site's medical editor. The CEO wants a one-line headline for the new page.", "prompt": "Which line is accurate?", "options": ["They can help; the cause is complex", "Depression is caused by low serotonin", "Science shows antidepressants fail"], "correctIndex": 0, "consequences": ["It matches both the review and its critics.", "The review found no consistent evidence for that.", "The review did not assess drug benefit."], "explanation": "Write the line that will still be true after the next study."}, "proReasoning": "Medical editors write lines that survive the next study. Keep claims to what the evidence supports.", "commonMistake": "Swapping one oversimplification for another.", "mentalModel": "Claim only what holds."}, "invest": {"call": {"kind": "theCall", "situation": "You're an investor in the site. Its traffic depends on readers' trust.", "prompt": "Why update the page quickly?", "options": ["The review legally requires an update", "Outdated claims put reader trust at risk", "Search engines reward older content more"], "correctIndex": 1, "consequences": ["No rule forces it; trust does.", "A health site lives on being right.", "Accuracy, not age, keeps readers."], "explanation": "For a health site, accuracy is the asset. A page the science has passed by is a liability."}, "proReasoning": "Investors in health media treat accuracy as an asset. A page the science has passed by is a liability.", "commonMistake": "Treating content updates as optional.", "mentalModel": "Accuracy is the asset."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Rewriting means admitting the old page was wrong.", "prompt": "How should you handle the change?", "options": ["Quietly delete the page", "Leave it, since many readers believe it", "Update it openly and cite the review"], "correctIndex": 2, "consequences": ["Readers who relied on it get no explanation.", "Popularity does not make it accurate.", "Openness keeps trust and shows readers the evidence."], "explanation": "Correct in the open and show the evidence. Hiding the change costs more trust than it saves."}, "proReasoning": "Founders of health products correct mistakes in the open. Showing the evidence builds more trust than hiding the change.", "commonMistake": "Hiding a correction to avoid looking wrong.", "mentalModel": "Correct in the open."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can help if the theory behind it was wrong.", "prompt": "What's the best analogy?", "options": ["Painkillers ease headaches, no shortage", "A wrong theory means the drug is fake", "Theories and drugs are the same thing"], "correctIndex": 0, "consequences": ["Critics used exactly that example.", "Drugs are judged by results, not by their backstory.", "A theory explains; a drug is tested."], "explanation": "A headache is not caused by a painkiller shortage, yet painkillers help. Relief does not prove the cause."}, "proReasoning": "Use the painkiller analogy: relief does not prove a shortage caused the pain.", "commonMistake": "Assuming a treatment's story must be true for it to work.", "mentalModel": "Relief is not proof of cause."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[])
